def list_incidents(workspace_id, connection_id=None, source=None, query=None, status=None, tags=None, time_from=None, time_to=None, sort=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0395000" if __import__("os").path.isdir("./environment_mix/0395000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return dt

    def _log(status, error=None, cost_units=0):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + base64.b32encode(os.urandom(16)).decode("ascii").rstrip("=").lower(),
            "endpoint": "list_incidents",
            "workspace_id": workspace_id,
            "connection_id": _resolved_conn_id[0],
            "credential_id": None,
            "status": status,
            "error": error,
            "cost_units": cost_units,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _iso(_now),
        })
        _save("request_logs.json", logs)

    def _is_ulid(prefix, v):
        return isinstance(v, str) and re.match(r"^" + re.escape(prefix) + r"_[0-9A-HJKMNP-TV-Z]{26}$", v) is not None

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a date-time string", field=field)
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} is malformed; expected RFC3339 date-time", field=field)

    def _decode_cursor(cur):
        if cur is None:
            return 0, None
        if not isinstance(cur, str) or not cur:
            return None, _err("VALIDATION_ERROR", "cursor must be a non-empty string", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                return None, _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
            return off, None
        except Exception:
            return None, _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

    def _encode_cursor(off):
        payload = json.dumps({"offset": off}, separators=(",", ":"), sort_keys=True).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    # Resolve workspace/connection id for logging even on early validation errors
    _resolved_conn_id = [connection_id]

    # Validate inputs
    if not _is_ulid("ddws", workspace_id):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid workspace_id format", "field": "workspace_id"})
        return _err("VALIDATION_ERROR", "Invalid workspace_id format", field="workspace_id")
    if connection_id is not None and not _is_ulid("ddconn", connection_id):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid connection_id format", "field": "connection_id"})
        return _err("VALIDATION_ERROR", "Invalid connection_id format", field="connection_id")
    if source is not None and source not in ("live", "cache"):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid source", "field": "source"})
        return _err("VALIDATION_ERROR", "Invalid source", field="source")
    if source is None:
        source = "cache"
    if query is not None and (not isinstance(query, str)):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "query must be a string", "field": "query"})
        return _err("VALIDATION_ERROR", "query must be a string", field="query")
    if status is not None and status not in ("active", "resolved", "triggered", "unknown"):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid status", "field": "status"})
        return _err("VALIDATION_ERROR", "Invalid status", field="status")
    if tags is not None:
        if not isinstance(tags, list) or any(not isinstance(t, str) for t in tags):
            _log("error", error={"code": "VALIDATION_ERROR", "message": "tags must be an array of strings", "field": "tags"})
            return _err("VALIDATION_ERROR", "tags must be an array of strings", field="tags")
    tf, e = _parse_dt(time_from, "time_from")
    if e:
        _log("error", error=e["error"])
        return e
    tt, e = _parse_dt(time_to, "time_to")
    if e:
        _log("error", error=e["error"])
        return e
    if tf and tt and tf > tt:
        er = _err("VALIDATION_ERROR", "time_from must be <= time_to", field="time_from")
        _log("error", error=er["error"])
        return er
    if sort is not None and sort not in ("created_at", "-created_at", "updated_at", "-updated_at"):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid sort", "field": "sort"})
        return _err("VALIDATION_ERROR", "Invalid sort", field="sort")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("error", error={"code": "VALIDATION_ERROR", "message": "limit must be between 1 and 100", "field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100", field="limit")
    offset, e = _decode_cursor(cursor)
    if e:
        _log("error", error=e["error"])
        return e

    # Resolve workspace and a usable connection
    workspaces = _load("workspaces.json")
    conns = _load("datadog_connections.json")
    resources = _load("dd_resources.json")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None or ws.get("status") == "deleted":
        _log("error", error={"code": "NOT_FOUND", "message": "Workspace not found"})
        return _err("NOT_FOUND", "Workspace not found")

    conn = None
    if connection_id is not None:
        conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == connection_id and c.get("workspace_id") == workspace_id), None)
        if conn is None:
            _log("error", error={"code": "NOT_FOUND", "message": "Connection not found for workspace"})
            return _err("NOT_FOUND", "Connection not found for workspace")
        _resolved_conn_id[0] = conn.get("id")
    else:
        dflt = ws.get("default_datadog_connection_id")
        if isinstance(dflt, str):
            c0 = next((c for c in conns if isinstance(c, dict) and c.get("id") == dflt and c.get("workspace_id") == workspace_id), None)
            if c0 is not None:
                conn = c0
        if conn is None:
            conn = next((c for c in conns if isinstance(c, dict) and c.get("workspace_id") == workspace_id and c.get("status") == "active"), None)
        if conn is None:
            # No combination in store can serve the call
            _resolved_conn_id[0] = None
            _log("error", error={"code": "UNAUTHORIZED", "message": "No active Datadog connection available for workspace"})
            return _err("UNAUTHORIZED", "No active Datadog connection available for workspace")
        _resolved_conn_id[0] = conn.get("id")

    # Enforce connection active when source=live (outbound calls). For cache reads, allow any.
    if source == "live" and conn.get("status") != "active":
        _log("error", error={"code": "UNAUTHORIZED", "message": "Datadog connection is not active"})
        return _err("UNAUTHORIZED", "Datadog connection is not active")

    # Serve from cache (the datastore has cached rows; "live" may refresh, but offline implementation returns cache)
    rows = [r for r in resources if isinstance(r, dict)
            and r.get("workspace_id") == workspace_id
            and r.get("connection_id") == conn.get("id")
            and r.get("resource_type") == "incident"]

    # Filters
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if tags:
        want = [t for t in tags if isinstance(t, str) and t]
        if want:
            def _has_all(rt):
                rtg = rt.get("tags") or []
                if not isinstance(rtg, list):
                    return False
                srtg = set([x for x in rtg if isinstance(x, str)])
                for w in want:
                    if w not in srtg:
                        return False
                return True
            rows = [r for r in rows if _has_all(r)]
    if query is not None and query.strip():
        q = query.strip().lower()
        def _match(r):
            if isinstance(r.get("name"), str) and q in r["name"].lower():
                return True
            attrs = r.get("attributes")
            if isinstance(attrs, dict):
                try:
                    blob = json.dumps(attrs, ensure_ascii=False).lower()
                    if q in blob:
                        return True
                except Exception:
                    pass
            rtg = r.get("tags") or []
            if isinstance(rtg, list):
                for t in rtg:
                    if isinstance(t, str) and q in t.lower():
                        return True
            return False
        rows = [r for r in rows if _match(r)]
    if tf or tt:
        def _dt(s):
            if not isinstance(s, str):
                return None
            try:
                ss = s[:-1] + "+00:00" if s.endswith("Z") else s
                dt = datetime.datetime.fromisoformat(ss)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except ValueError:
                return None
        def _in_window(r):
            c = _dt(r.get("created_at"))
            u = _dt(r.get("updated_at"))
            pivot = u or c
            if pivot is None:
                return True
            if tf and pivot < tf:
                return False
            if tt and pivot > tt:
                return False
            return True
        rows = [r for r in rows if _in_window(r)]

    # Sort
    if sort is None:
        sort = "-updated_at"

    def _key_dt(v):
        if not isinstance(v, str):
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        try:
            ss = v[:-1] + "+00:00" if v.endswith("Z") else v
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    reverse = sort.startswith("-")
    field = sort[1:] if reverse else sort
    if field not in ("created_at", "updated_at"):
        field = "updated_at"
    rows.sort(key=lambda r: _key_dt(r.get(field)), reverse=reverse)

    total = len(rows)
    page = rows[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    resp = {
        "data": page,
        "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor, "source": source},
    }
    _log("ok", cost_units=0)
    return resp

def get_incident(workspace_id, incident_id, connection_id=None, source=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0395000" if __import__("os").path.isdir("./environment_mix/0395000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
