            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return dt

    def _log(status, error=None, cost_units=0):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + base64.b32encode(os.urandom(16)).decode("ascii").rstrip("=").lower(),
            "endpoint": "get_metrics",
            "workspace_id": workspace_id,
            "connection_id": _resolved_conn_id[0],
            "credential_id": None,
            "status": status,
            "error": error,
            "cost_units": cost_units,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _iso(_now),
        })
        _save("request_logs.json", logs)

    def _is_ulid(prefix, v):
        return isinstance(v, str) and re.match(r"^" + re.escape(prefix) + r"_[0-9A-HJKMNP-TV-Z]{26}$", v) is not None

    def _parse_dt(s, field):
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a date-time string", field=field)
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} is malformed; expected RFC3339 date-time", field=field)

    def _gen_id(prefix):
        return prefix + "_" + base64.b32encode(os.urandom(16)).decode("ascii").rstrip("=")

    def _stable_hash(obj):
        blob = json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return hashlib.sha256(blob).hexdigest()

    # Validate
    if not _is_ulid("ddws", workspace_id):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid workspace_id format", "field": "workspace_id"})
        return _err("VALIDATION_ERROR", "Invalid workspace_id format", field="workspace_id")
    if connection_id is not None and not _is_ulid("ddconn", connection_id):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid connection_id format", "field": "connection_id"})
        return _err("VALIDATION_ERROR", "Invalid connection_id format", field="connection_id")
    if not isinstance(query, str) or not query.strip():
        _log("error", error={"code": "VALIDATION_ERROR", "message": "query must be a non-empty string", "field": "query"})
        return _err("VALIDATION_ERROR", "query must be a non-empty string", field="query")

    tf, e = _parse_dt(time_from, "time_from")
    if e:
        _log("error", error=e["error"])
        return e
    tt, e = _parse_dt(time_to, "time_to")
    if e:
        _log("error", error=e["error"])
        return e

    if interval_seconds is None:
        interval_seconds = 60
    if not isinstance(interval_seconds, int) or interval_seconds < 1:
        _log("error", error={"code": "VALIDATION_ERROR", "message": "interval_seconds must be >= 1", "field": "interval_seconds"})
        return _err("VALIDATION_ERROR", "interval_seconds must be >= 1", field="interval_seconds")

    if max_points is None:
        max_points = 300
    if not isinstance(max_points, int) or max_points < 1:
        _log("error", error={"code": "VALIDATION_ERROR", "message": "max_points must be >= 1", "field": "max_points"})
        return _err("VALIDATION_ERROR", "max_points must be >= 1", field="max_points")

    # Resolve workspace/connection (must be active for outbound call)
    workspaces = _load("workspaces.json")
    conns = _load("datadog_connections.json")
    runs = _load("dd_query_runs.json")
    if not isinstance(runs, list):
        runs = []

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None or ws.get("status") == "deleted":
        _log("error", error={"code": "NOT_FOUND", "message": "Workspace not found"})
        return _err("NOT_FOUND", "Workspace not found")

    conn = None
    if connection_id is not None:
        conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == connection_id and c.get("workspace_id") == workspace_id), None)
        if conn is None:
            _log("error", error={"code": "NOT_FOUND", "message": "Connection not found for workspace"})
            return _err("NOT_FOUND", "Connection not found for workspace")
        _resolved_conn_id[0] = conn.get("id")
    else:
        dflt = ws.get("default_datadog_connection_id")
        if isinstance(dflt, str):
            c0 = next((c for c in conns if isinstance(c, dict) and c.get("id") == dflt and c.get("workspace_id") == workspace_id), None)
            if c0 is not None:
                conn = c0
        if conn is None:
            conn = next((c for c in conns if isinstance(c, dict) and c.get("workspace_id") == workspace_id and c.get("status") == "active"), None)
        if conn is None:
            _resolved_conn_id[0] = None
            _log("error", error={"code": "UNAUTHORIZED", "message": "No active Datadog connection available for workspace"})
            return _err("UNAUTHORIZED", "No active Datadog connection available for workspace")
        _resolved_conn_id[0] = conn.get("id")

    # Prepare normalized request
    req_obj = {
        "query": query.strip(),
        "time_from": _iso(tf),
        "time_to": _iso(tt),
        "interval_seconds": interval_seconds,
        "max_points": max_points,
    }

    # Idempotency reuse (vendor says may deduplicate when idempotency_key is provided)
    if idempotency_key is not None:
        if not isinstance(idempotency_key, str) or not idempotency_key:
            _log("error", error={"code": "VALIDATION_ERROR", "message": "idempotency_key must be a non-empty string", "field": "idempotency_key"})
            return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string", field="idempotency_key")
        existing = next((r for r in runs if isinstance(r, dict)
                         and r.get("workspace_id") == workspace_id
                         and r.get("connection_id") == conn.get("id")
                         and r.get("query_type") == "metrics"
                         and r.get("request") == req_obj
                         and r.get("status") in ("running", "queued", "succeeded")), None)
        if existing is not None:
            _log("ok", cost_units=int(existing.get("cost_units") or 0))
            return {"data": existing, "meta": {"reused": True}}

    # Create dd_query_runs row queued
    run_id = _gen_id("ddqr")
    requested_at = _iso(_now)
    run = {
        "id": run_id,
        "workspace_id": workspace_id,
        "connection_id": conn.get("id"),
        "query_type": "metrics",
        "status": "queued",
        "requested_at": requested_at,
        "started_at": None,
        "finished_at": None,
        "time_from": _iso(tf),
        "time_to": _iso(tt),
        "request": req_obj,
        "result": None,
        "next_page_cursor": None,
        "error": None,
        "http_status": None,
        "cost_units": 1,
        "created_at": requested_at,
        "updated_at": requested_at,
    }
    runs.append(run)
    _save("dd_query_runs.json", runs)

    # If invalid time bounds, mark failed and do not "call datadog"
    if tf >= tt:
        for r in runs:
            if isinstance(r, dict) and r.get("id") == run_id:
                r["status"] = "failed"
                r["started_at"] = requested_at
                r["finished_at"] = requested_at
                r["error"] = {"code": "VALIDATION_ERROR", "message": "time_from must be < time_to", "field": "time_from"}
                r["http_status"] = None
                r["updated_at"] = requested_at
                break
        _save("dd_query_runs.json", runs)
        _log("error", error={"code": "VALIDATION_ERROR", "message": "time_from must be < time_to", "field": "time_from"}, cost_units=1)
        return _err("VALIDATION_ERROR", "time_from must be < time_to", field="time_from")

    # Enforce active connection for outbound call; if not active, fail without calling
    if conn.get("status") != "active":
        fail_at = _iso(datetime.datetime.now(datetime.timezone.utc))
        for r in runs:
            if isinstance(r, dict) and r.get("id") == run_id:
                r["status"] = "failed"
                r["started_at"] = requested_at
                r["finished_at"] = fail_at
                r["error"] = {"code": "UNAUTHORIZED", "message": "Datadog connection is not active"}
                r["updated_at"] = fail_at
                break
        _save("dd_query_runs.json", runs)
        _log("error", error={"code": "UNAUTHORIZED", "message": "Datadog connection is not active"}, cost_units=1)
        return _err("UNAUTHORIZED", "Datadog connection is not active")

    # Rate limit: count "outbound" calls per connection in last minute from request_logs
    rate = conn.get("rate_limit_per_minute")
    try:
        rate = int(rate)
    except Exception:
        rate = 60
    if rate < 1:
        rate = 1
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    window_start = _now - datetime.timedelta(minutes=1)
    outbound = 0
    for lg in logs:
        if not isinstance(lg, dict):
            continue
        if lg.get("connection_id") != conn.get("id"):
            continue
        ep = lg.get("endpoint")
        if ep in ("get_metrics", "get_logs", "list_traces", "get_active_hosts_count", "mute_host", "unmute_host", "schedule_downtime", "cancel_downtime"):
            ts = lg.get("timestamp")
            if isinstance(ts, str):
                try:
                    ss = ts[:-1] + "+00:00" if ts.endswith("Z") else ts
                    dt = datetime.datetime.fromisoformat(ss)
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=datetime.timezone.utc)
                    dt = dt.astimezone(datetime.timezone.utc)
                    if dt >= window_start:
                        outbound += 1
                except ValueError:
                    pass
    if outbound >= rate:
        fail_at = _iso(datetime.datetime.now(datetime.timezone.utc))
        for r in runs:
            if isinstance(r, dict) and r.get("id") == run_id:
                r["status"] = "failed"
                r["started_at"] = requested_at
                r["finished_at"] = fail_at
                r["error"] = {"code": "RATE_LIMIT", "message": "Rate limit exceeded for connection"}
                r["updated_at"] = fail_at
                break
        _save("dd_query_runs.json", runs)
        _log("error", error={"code": "RATE_LIMIT", "message": "Rate limit exceeded for connection"}, cost_units=1)
        return _err("RATE_LIMIT", "Rate limit exceeded for connection")

    # Offline "Datadog" call simulation: mark succeeded with empty series, but persist status transitions correctly
    started_at = _iso(datetime.datetime.now(datetime.timezone.utc))
    for r in runs:
        if isinstance(r, dict) and r.get("id") == run_id:
            r["status"] = "running"
            r["started_at"] = started_at
            r["updated_at"] = started_at
            break
    _save("dd_query_runs.json", runs)

    finished_at = _iso(datetime.datetime.now(datetime.timezone.utc))
    result = {
        "series": [],
        "query": req_obj["query"],
        "from": req_obj["time_from"],
        "to": req_obj["time_to"],
        "interval_seconds": interval_seconds,
        "max_points": max_points,
    }
    for r in runs:
        if isinstance(r, dict) and r.get("id") == run_id:
            r["status"] = "succeeded"
            r["finished_at"] = finished_at
            r["result"] = result
            r["http_status"] = 200
            r["updated_at"] = finished_at
            break
    _save("dd_query_runs.json", runs)

    run_row = next((r for r in runs if isinstance(r, dict) and r.get("id") == run_id), None)
    _log("ok", cost_units=1)
    return {"data": run_row, "meta": {"reused": False}}

def get_logs(workspace_id, query, time_from, time_to, connection_id=None, sort=None, limit=None, cursor=None, idempotency_key=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0395000" if __import__("os").path.isdir("./environment_mix/0395000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.now(datetime.timezone.utc)
    _resolved_conn_id = [connection_id]

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return dt

    def _log(status, error=None, cost_units=0):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + base64.b32encode(os.urandom(16)).decode("ascii").rstrip("=").lower(),
            "endpoint": "get_logs",
            "workspace_id": workspace_id,
            "connection_id": _resolved_conn_id[0],
            "credential_id": None,
            "status": status,
            "error": error,
            "cost_units": cost_units,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _iso(_now),
        })
        _save("request_logs.json", logs)

    def _is_ulid(prefix, v):
        return isinstance(v, str) and re.match(r"^" + re.escape(prefix) + r"_[0-9A-HJKMNP-TV-Z]{26}$", v) is not None

    def _parse_dt(s, field):
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a date-time string", field=field)
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} is malformed; expected RFC3339 date-time", field=field)

    def _decode_cursor(cur):
        if cur is None:
            return None, None
        if not isinstance(cur, str) or not cur:
            return None, _err("VALIDATION_ERROR", "cursor must be a non-empty string", field="cursor")
        return cur, None

    # Validate
    if not _is_ulid("ddws", workspace_id):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid workspace_id format", "field": "workspace_id"})
        return _err("VALIDATION_ERROR", "Invalid workspace_id format", field="workspace_id")
    if connection_id is not None and not _is_ulid("ddconn", connection_id):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid connection_id format", "field": "connection_id"})
        return _err("VALIDATION_ERROR", "Invalid connection_id format", field="connection_id")
    if not isinstance(query, str) or not query.strip():
        _log("error", error={"code": "VALIDATION_ERROR", "message": "query must be a non-empty string", "field": "query"})
        return _err("VALIDATION_ERROR", "query must be a non-empty string", field="query")
    tf, e = _parse_dt(time_from, "time_from")
    if e:
        _log("error", error=e["error"])
        return e
    tt, e = _parse_dt(time_to, "time_to")
    if e:
        _log("error", error=e["error"])
        return e
    if tf >= tt:
        er = _err("VALIDATION_ERROR", "time_from must be < time_to", field="time_from")
        _log("error", error=er["error"])
        return er
    if sort is None:
        sort = "-timestamp"
    if sort not in ("timestamp", "-timestamp"):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid sort", "field": "sort"})
        return _err("VALIDATION_ERROR", "Invalid sort", field="sort")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 1000:
        _log("error", error={"code": "VALIDATION_ERROR", "message": "limit must be between 1 and 1000", "field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 1000", field="limit")
    cur, e = _decode_cursor(cursor)
    if e:
        _log("error", error=e["error"])
        return e
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "idempotency_key must be a non-empty string", "field": "idempotency_key"})
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string", field="idempotency_key")

    # Resolve workspace/connection
    workspaces = _load("workspaces.json")
    conns = _load("datadog_connections.json")
    runs = _load("dd_query_runs.json")
    if not isinstance(runs, list):
        runs = []

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None or ws.get("status") == "deleted":
        _log("error", error={"code": "NOT_FOUND", "message": "Workspace not found"})
        return _err("NOT_FOUND", "Workspace not found")

    conn = None
    if connection_id is not None:
        conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == connection_id and c.get("workspace_id") == workspace_id), None)
        if conn is None:
            _log("error", error={"code": "NOT_FOUND", "message": "Connection not found for workspace"})
            return _err("NOT_FOUND", "Connection not found for workspace")
        _resolved_conn_id[0] = conn.get("id")
    else:
        dflt = ws.get("default_datadog_connection_id")
        if isinstance(dflt, str):
            c0 = next((c for c in conns if isinstance(c, dict) and c.get("id") == dflt and c.get("workspace_id") == workspace_id), None)
            if c0 is not None:
                conn = c0
        if conn is None:
            conn = next((c for c in conns if isinstance(c, dict) and c.get("workspace_id") == workspace_id and c.get("status") == "active"), None)
        if conn is None:
            _resolved_conn_id[0] = None
            _log("error", error={"code": "UNAUTHORIZED", "message": "No active Datadog connection available for workspace"})
            return _err("UNAUTHORIZED", "No active Datadog connection available for workspace")
        _resolved_conn_id[0] = conn.get("id")

    # Create run (queued -> running -> succeeded) with empty results (offline)
    def _gen_id(prefix):
        return prefix + "_" + base64.b32encode(os.urandom(16)).decode("ascii").rstrip("=")

    req_obj = {
        "query": query.strip(),
        "time_from": _iso(tf),
        "time_to": _iso(tt),
        "sort": sort,
        "limit": limit,
        "cursor": cur,
    }

    if idempotency_key is not None:
        existing = next((r for r in runs if isinstance(r, dict)
                         and r.get("workspace_id") == workspace_id
                         and r.get("connection_id") == conn.get("id")
