        "workspace_id": workspace_id,
        "connection_id": conn.get("id"),
        "query_type": "logs",
        "status": "queued",
        "requested_at": requested_at,
        "started_at": None,
        "finished_at": None,
        "time_from": _iso(tf),
        "time_to": _iso(tt),
