                try:
                    ss = ts[:-1] + "+00:00" if ts.endswith("Z") else ts
                    dt = datetime.datetime.fromisoformat(ss)
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=datetime.timezone.utc)
                    dt = dt.astimezone(datetime.timezone.utc)
                    if dt >= window_start:
                        outbound += 1
                except ValueError:
                    pass
    if outbound >= rate:
        fail_at = _iso(datetime.datetime.now(datetime.timezone.utc))
        for r in runs:
            if isinstance(r, dict) and r.get("id") == run_id:
                r["status"] = "failed"
                r["started_at"] = requested_at
                r["finished_at"] = fail_at
                r["error"] = {"code": "RATE_LIMIT", "message": "Rate limit exceeded for connection"}
                r["updated_at"] = fail_at
                break
        _save("dd_query_runs.json", runs)
        _log("error", error={"code": "RATE_LIMIT", "message": "Rate limit exceeded for connection"}, cost_units=1)
