    started_at = _iso(datetime.datetime.now(datetime.timezone.utc))
    for r in runs:
        if isinstance(r, dict) and r.get("id") == run_id:
            r["status"] = "running"
            r["started_at"] = started_at
            r["updated_at"] = started_at
            break
    _save("dd_query_runs.json", runs)

    finished_at = _iso(datetime.datetime.now(datetime.timezone.utc))
    result = {"events": [], "count": 0}
    next_cursor = None
