def get_monitors(workspace_id, connection_id=None, source=None, query=None, status=None, tags=None, sort=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, hashlib, base64

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0395000" if __import__("os").path.isdir("./environment_mix/0395000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(endpoint, ws_id, conn_id, status_code, error_code=None, units=0, meta=None):
        row = {
            "id": "ddreq_" + base64.b32encode(os.urandom(16)).decode("utf-8").rstrip("=").lower(),
            "endpoint": endpoint,
            "workspace_id": ws_id,
            "connection_id": conn_id,
            "status": status_code,
            "error_code": error_code,
            "cost_units": units,
            "meta": meta or {},
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now_iso(),
        }
        reqs = _load("dd_request_log.json")
        if not isinstance(reqs, list):
            reqs = []
        reqs.append(row)
        _save("dd_request_log.json", reqs)

    def _validate_ulid(prefix, v, field):
        if v is None:
            return None
        if not isinstance(v, str):
            return _err("VALIDATION_ERROR", f"{field} must be a string")
        pat = r"^" + re.escape(prefix) + r"_[0-9A-HJKMNP-TV-Z]{26}$"
        if not re.match(pat, v):
            return _err("VALIDATION_ERROR", f"Invalid {field}")
        return None

    def _resolve_ws_conn(ws_id, conn_id_opt):
        wss = _load("workspaces.json")
        conns = _load("datadog_connections.json")
        ws = next((w for w in wss if isinstance(w, dict) and w.get("id") == ws_id), None)
        if ws is None or ws.get("status") == "deleted":
            return None, None, _err("NOT_FOUND", "Workspace not found")
        if ws.get("status") != "active":
            return None, None, _err("UNAUTHORIZED", "Workspace is not active")

        candidates = []
        if conn_id_opt:
            c = next((c for c in conns if isinstance(c, dict) and c.get("id") == conn_id_opt), None)
            if c is None:
                return None, None, _err("NOT_FOUND", "Connection not found")
            if c.get("workspace_id") != ws_id:
                return None, None, _err("VALIDATION_ERROR", "connection_id must belong to workspace")
            candidates = [c]
        else:
            def_id = ws.get("default_datadog_connection_id")
            if def_id:
                c = next((c for c in conns if isinstance(c, dict) and c.get("id") == def_id and c.get("workspace_id") == ws_id), None)
                if c:
                    candidates.append(c)
            candidates.extend([c for c in conns if isinstance(c, dict) and c.get("workspace_id") == ws_id])

        active = next((c for c in candidates if c.get("status") == "active"), None)
        if not active:
            return None, None, _err("UNAUTHORIZED", "No active Datadog connection available for workspace")
        return ws, active, None

    def _rate_limited(conn):
        # Count request log entries in the last 60 seconds for this connection.
        rate = conn.get("rate_limit_per_minute")
        if not isinstance(rate, int) or rate < 1:
            rate = 60
        reqs = _load("dd_request_log.json")
        if not isinstance(reqs, list):
            reqs = []
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        n = 0
        for r in reqs:
            if not isinstance(r, dict):
                continue
            if r.get("connection_id") != conn.get("id"):
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts and ts >= cutoff:
                n += 1
        return n >= rate

    def _encode_cursor(offset):
        payload = json.dumps({"o": offset}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return 0, None
        if not isinstance(cur, str) or not cur:
            return 0, _err("VALIDATION_ERROR", "cursor must be a string")
        try:
            pad = "=" * (-len(cur) % 4)
            data = base64.urlsafe_b64decode((cur + pad).encode("utf-8"))
            obj = json.loads(data.decode("utf-8"))
            o = obj.get("o", 0)
            if not isinstance(o, int) or o < 0:
                return 0, _err("VALIDATION_ERROR", "Invalid cursor")
            return o, None
        except Exception:
            return 0, _err("VALIDATION_ERROR", "Invalid cursor")

    # Validate inputs
    e = _validate_ulid("ddws", workspace_id, "workspace_id")
    if e:
        _log("get_monitors", workspace_id, connection_id, "error", error_code=e["error"]["code"])
        return e
    e = _validate_ulid("ddconn", connection_id, "connection_id")
    if e:
        _log("get_monitors", workspace_id, connection_id, "error", error_code=e["error"]["code"])
        return e
    if source is None:
        source = "cache"
    if source not in ("live", "cache"):
        e = _err("VALIDATION_ERROR", "Invalid source")
        _log("get_monitors", workspace_id, connection_id, "error", error_code=e["error"]["code"])
        return e
    if query is not None and not isinstance(query, str):
