            if not tagset.issubset(rtags):
                continue

        if q:
            hay = []
            nm = r.get("name")
            if isinstance(nm, str):
                hay.append(nm.lower())
            rt = r.get("tags") or []
            if isinstance(rt, list):
                hay.append(" ".join([t.lower() for t in rt if isinstance(t, str)]))
            attrs = r.get("attributes")
            if isinstance(attrs, dict):
                try:
                    hay.append(json.dumps(attrs, ensure_ascii=False).lower())
                except Exception:
                    pass
            if q not in " ".join(hay):
                continue

        rows.append(r)

    def _key_name(r):
        v = r.get("name")
        return (v or "").lower()

    def _key_updated(r):
        dt = _parse_dt(r.get("updated_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
