    elif sort == "-name":
        keyfn = _key_name
        reverse = True
    elif sort == "updated_at":
        keyfn = _key_updated
        reverse = False
    elif sort == "-updated_at":
        keyfn = _key_updated
        reverse = True
    rows.sort(key=keyfn, reverse=reverse)

