    def _validate_ulid(prefix, v, field):
        if v is None:
            return None
        if not isinstance(v, str):
            return _err("VALIDATION_ERROR", f"{field} must be a string")
        pat = r"^" + re.escape(prefix) + r"_[0-9A-HJKMNP-TV-Z]{26}$"
        if not re.match(pat, v):
            return _err("VALIDATION_ERROR", f"Invalid {field}")
        return None

    def _resolve_ws_conn(ws_id, conn_id_opt):
        wss = _load("workspaces.json")
        conns = _load("datadog_connections.json")
