            return None, None, _err("NOT_FOUND", "Workspace not found")
        if ws.get("status") != "active":
            return None, None, _err("UNAUTHORIZED", "Workspace is not active")

        candidates = []
        if conn_id_opt:
            c = next((c for c in conns if isinstance(c, dict) and c.get("id") == conn_id_opt), None)
            if c is None:
                return None, None, _err("NOT_FOUND", "Connection not found")
            if c.get("workspace_id") != ws_id:
                return None, None, _err("VALIDATION_ERROR", "connection_id must belong to workspace")
            candidates = [c]
        else:
            def_id = ws.get("default_datadog_connection_id")
            if def_id:
                c = next((c for c in conns if isinstance(c, dict) and c.get("id") == def_id and c.get("workspace_id") == ws_id), None)
                if c:
                    candidates.append(c)
            candidates.extend([c for c in conns if isinstance(c, dict) and c.get("workspace_id") == ws_id])

        active = next((c for c in candidates if c.get("status") == "active"), None)
