            return None, None, _err("UNAUTHORIZED", "No active Datadog connection available for workspace")
        return ws, active, None

    def _rate_limited(conn):
        rate = conn.get("rate_limit_per_minute")
        if not isinstance(rate, int) or rate < 1:
            rate = 60
        reqs = _load("dd_request_log.json")
