            "credential_id": None,
            "status": status,
            "error": error,
            "cost_units": cost_units,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _iso(_now),
        })
        _save("request_logs.json", logs)

    def _is_ulid(prefix, v):
        return isinstance(v, str) and re.match(r"^" + re.escape(prefix) + r"_[0-9A-HJKMNP-TV-Z]{26}$", v) is not None

    if not _is_ulid("ddws", workspace_id):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid workspace_id format", "field": "workspace_id"})
        return _err("VALIDATION_ERROR", "Invalid workspace_id format", field="workspace_id")
    if connection_id is not None and not _is_ulid("ddconn", connection_id):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid connection_id format", "field": "connection_id"})
        return _err("VALIDATION_ERROR", "Invalid connection_id format", field="connection_id")
    if not isinstance(dashboard_id, str) or not dashboard_id.strip():
        _log("error", error={"code": "VALIDATION_ERROR", "message": "dashboard_id must be a non-empty string", "field": "dashboard_id"})
        return _err("VALIDATION_ERROR", "dashboard_id must be a non-empty string", field="dashboard_id")
    if source is not None and source not in ("live", "cache"):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid source", "field": "source"})
        return _err("VALIDATION_ERROR", "Invalid source", field="source")
    if source is None:
        source = "cache"

    workspaces = _load("workspaces.json")
    conns = _load("datadog_connections.json")
    resources = _load("dd_resources.json")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None or ws.get("status") == "deleted":
        _log("error", error={"code": "NOT_FOUND", "message": "Workspace not found"})
        return _err("NOT_FOUND", "Workspace not found")

    conn = None
    if connection_id is not None:
        conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == connection_id and c.get("workspace_id") == workspace_id), None)
        if conn is None:
            _log("error", error={"code": "NOT_FOUND", "message": "Connection not found for workspace"})
            return _err("NOT_FOUND", "Connection not found for workspace")
        _resolved_conn_id[0] = conn.get("id")
    else:
        dflt = ws.get("default_datadog_connection_id")
        if isinstance(dflt, str):
            c0 = next((c for c in conns if isinstance(c, dict) and c.get("id") == dflt and c.get("workspace_id") == workspace_id), None)
            if c0 is not None:
                conn = c0
        if conn is None:
            conn = next((c for c in conns if isinstance(c, dict) and c.get("workspace_id") == workspace_id and c.get("status") == "active"), None)
        if conn is None:
            _resolved_conn_id[0] = None
            _log("error", error={"code": "UNAUTHORIZED", "message": "No active Datadog connection available for workspace"})
            return _err("UNAUTHORIZED", "No active Datadog connection available for workspace")
        _resolved_conn_id[0] = conn.get("id")

    if source == "live" and conn.get("status") != "active":
        _log("error", error={"code": "UNAUTHORIZED", "message": "Datadog connection is not active"})
        return _err("UNAUTHORIZED", "Datadog connection is not active")

    row = next((r for r in resources if isinstance(r, dict)
                and r.get("workspace_id") == workspace_id
                and r.get("connection_id") == conn.get("id")
                and r.get("resource_type") == "dashboard"
                and str(r.get("datadog_id")) == dashboard_id), None)

    if row is None:
        _log("ok", cost_units=0)
        return {"data": None, "meta": {"found": False, "source": source}}

    _log("ok", cost_units=0)
    return {"data": row, "meta": {"found": True, "source": source}}

