                return None, None, _err("VALIDATION_ERROR", "connection_id must belong to workspace")
            candidates = [c]
        else:
            def_id = ws.get("default_datadog_connection_id")
            if def_id:
                c = next((c for c in conns if isinstance(c, dict) and c.get("id") == def_id and c.get("workspace_id") == ws_id), None)
                if c:
                    candidates.append(c)
            candidates.extend([c for c in conns if isinstance(c, dict) and c.get("workspace_id") == ws_id])

        active = next((c for c in candidates if c.get("status") == "active"), None)
        if not active:
            return None, None, _err("UNAUTHORIZED", "No active Datadog connection available for workspace")
        return ws, active, None

    def _rate_limited(conn):
        rate = conn.get("rate_limit_per_minute")
        if not isinstance(rate, int) or rate < 1:
            rate = 60
        reqs = _load("dd_request_log.json")
        if not isinstance(reqs, list):
            reqs = []
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        n = 0
        for r in reqs:
            if not isinstance(r, dict):
                continue
            if r.get("connection_id") != conn.get("id"):
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts and ts >= cutoff:
                n += 1
        return n >= rate

    def _new_id(prefix):
        return prefix + "_" + base64.b32encode(os.urandom(16)).decode("utf-8").rstrip("=").upper()

    def _stable_idempo(ws_id, conn_id, payload):
        s = json.dumps({"ws": ws_id, "conn": conn_id, **payload}, sort_keys=True, separators=(",", ":"))
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    # Validate inputs
    e = _validate_ulid("ddws", workspace_id, "workspace_id")
    if e:
        _log("list_traces", workspace_id, connection_id, "error", error_code=e["error"]["code"])
        return e
    e = _validate_ulid("ddconn", connection_id, "connection_id")
    if e:
        _log("list_traces", workspace_id, connection_id, "error", error_code=e["error"]["code"])
        return e
    if not isinstance(query, str) or not query.strip():
        e = _err("VALIDATION_ERROR", "query must be a non-empty string")
        _log("list_traces", workspace_id, connection_id, "error", error_code=e["error"]["code"])
        return e
    dt_from, e1 = _parse_dt_strict(time_from, "time_from")
    if e1:
        _log("list_traces", workspace_id, connection_id, "error", error_code=e1["error"]["code"])
        return e1
    dt_to, e2 = _parse_dt_strict(time_to, "time_to")
    if e2:
        _log("list_traces", workspace_id, connection_id, "error", error_code=e2["error"]["code"])
        return e2
    if not (dt_from < dt_to):
        e = _err("VALIDATION_ERROR", "time_from must be < time_to")
        _log("list_traces", workspace_id, connection_id, "error", error_code=e["error"]["code"])
        return e
    if sort is None:
        sort = "-timestamp"
    if sort not in ("timestamp", "-timestamp"):
        e = _err("VALIDATION_ERROR", "Invalid sort")
        _log("list_traces", workspace_id, connection_id, "error", error_code=e["error"]["code"])
        return e
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 1000:
        e = _err("VALIDATION_ERROR", "limit must be between 1 and 1000")
        _log("list_traces", workspace_id, connection_id, "error", error_code=e["error"]["code"])
        return e
    if cursor is not None and (not isinstance(cursor, str) or not cursor):
        e = _err("VALIDATION_ERROR", "cursor must be a string")
        _log("list_traces", workspace_id, connection_id, "error", error_code=e["error"]["code"])
        return e
    if idempotency_key is not None and not isinstance(idempotency_key, str):
        e = _err("VALIDATION_ERROR", "idempotency_key must be a string")
        _log("list_traces", workspace_id, connection_id, "error", error_code=e["error"]["code"])
        return e

    ws, conn, er = _resolve_ws_conn(workspace_id, connection_id)
    if er:
        _log("list_traces", workspace_id, connection_id, "error", error_code=er["error"]["code"])
        return er

    # Create dd_query_runs row with status queued, then progress.
    runs = _load("dd_query_runs.json")
    if not isinstance(runs, list):
        runs = []

    normalized_req = {
        "query": query,
        "time_from": dt_from.isoformat(),
        "time_to": dt_to.isoformat(),
        "sort": sort,
        "limit": limit,
        "cursor": cursor,
    }
    dedupe_key = idempotency_key or _stable_idempo(workspace_id, conn.get("id"), {"type": "traces", **normalized_req})

    # Best-effort idempotency: if a run with same workspace/connection/query_type and same request+key exists and is running/succeeded, return it.
    existing = None
    for r in runs:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id or r.get("connection_id") != conn.get("id"):
            continue
        if r.get("query_type") != "traces":
            continue
        req = r.get("request")
        if isinstance(req, dict) and req.get("dedupe_key") == dedupe_key:
            existing = r
            break

    if existing and existing.get("status") in ("running", "queued", "succeeded"):
        _log("list_traces", workspace_id, conn.get("id"), "ok", units=existing.get("cost_units", 0), meta={"deduped": True})
        return {
            "workspace_id": workspace_id,
            "connection_id": conn.get("id"),
            "run": existing,
            "data": (existing.get("result") or {}).get("traces", []),
            "meta": {
                "next_cursor": existing.get("next_page_cursor"),
                "has_more": bool(existing.get("next_page_cursor")),
                "run_id": existing.get("id"),
                "deduped": True,
            },
        }

    run_id = _new_id("ddqr")
    now = _now_iso()
    run_row = {
        "id": run_id,
        "workspace_id": workspace_id,
        "connection_id": conn.get("id"),
        "query_type": "traces",
        "status": "queued",
        "requested_at": now,
        "started_at": None,
        "finished_at": None,
        "time_from": dt_from.isoformat(),
        "time_to": dt_to.isoformat(),
        "request": {"dedupe_key": dedupe_key, **normalized_req},
        "result": None,
        "next_page_cursor": None,
        "error": None,
        "http_status": None,
        "cost_units": 1,
        "created_at": now,
        "updated_at": now,
    }
    runs.append(run_row)
    _save("dd_query_runs.json", runs)

    # Rate limit check: if exceeded, fail the run without "calling" Datadog.
    if _rate_limited(conn):
        # Transition queued -> running -> failed not allowed; must go queued->running? transitions allow queued->running or cancelled.
        # We'll keep it queued but mark failed is invalid; instead transition queued->running then running->failed.
        # If can't, return INVALID_TRANSITION.
        # Apply transitions explicitly.
        run_row["status"] = "running"
        run_row["started_at"] = _now_iso()
        run_row["updated_at"] = _now_iso()

        run_row["status"] = "failed"
        run_row["finished_at"] = _now_iso()
        run_row["updated_at"] = _now_iso()
        run_row["error"] = {"code": "RATE_LIMIT", "message": "Datadog rate limit exceeded for connection"}
        run_row["http_status"] = 429
        # persist update
        for i, r in enumerate(runs):
            if isinstance(r, dict) and r.get("id") == run_id:
                runs[i] = run_row
                break
        _save("dd_query_runs.json", runs)

        _log("list_traces", workspace_id, conn.get("id"), "error", error_code="RATE_LIMIT", units=run_row["cost_units"])
        return _err("RATE_LIMIT", "Datadog rate limit exceeded for connection", run_id=run_id)

    # Offline "execution": mark succeeded with empty results and deterministic paging behavior.
    run_row["status"] = "running"
    run_row["started_at"] = _now_iso()
    run_row["updated_at"] = _now_iso()

    # No live Datadog; return empty traces.
    result = {"traces": [], "info": {"note": "offline datastore: no live Datadog calls performed"}}
    run_row["result"] = result
    run_row["next_page_cursor"] = None
    run_row["http_status"] = 200
    run_row["status"] = "succeeded"
    run_row["finished_at"] = _now_iso()
    run_row["updated_at"] = _now_iso()

    for i, r in enumerate(runs):
        if isinstance(r, dict) and r.get("id") == run_id:
            runs[i] = run_row
            break
    _save("dd_query_runs.json", runs)

    _log("list_traces", workspace_id, conn.get("id"), "ok", units=run_row["cost_units"], meta={"run_id": run_id})

    return {
        "workspace_id": workspace_id,
        "connection_id": conn.get("id"),
        "run": run_row,
        "data": result["traces"],
        "meta": {"next_cursor": None, "has_more": False, "run_id": run_id},
    }

def mute_host(workspace_id, connection_id, idempotency_key, host_id=None, datadog_host_id=None, end=None, message=None, override=None, **_extra):
    import json, os, datetime, time, re, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0395000" if __import__("os").path.isdir("./environment_mix/0395000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _log(status, error=None, cost_units=0, resolved_connection_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + base64.b32encode(os.urandom(16)).decode("ascii").rstrip("=").lower(),
            "endpoint": "mute_host",
            "workspace_id": workspace_id,
            "connection_id": resolved_connection_id if resolved_connection_id is not None else connection_id,
            "credential_id": None,
            "status": status,
            "error": error,
            "cost_units": cost_units,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _iso(_now),
        })
        _save("request_logs.json", logs)

    def _is_ulid(prefix, v):
        return isinstance(v, str) and re.match(r"^" + re.escape(prefix) + r"_[0-9A-HJKMNP-TV-Z]{26}$", v) is not None

    def _gen_id(prefix):
        return prefix + "_" + base64.b32encode(os.urandom(16)).decode("ascii").rstrip("=").upper()

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a date-time string", field=field)
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be ISO 8601 date-time", field=field)

    def _normalize_request():
        # Normalize for stable idempotency derivation even if caller passes explicit idempotency_key.
        dt_end, _ = _parse_dt(end, "end")
        return {
            "end": _iso(dt_end),
            "message": message if isinstance(message, str) else None,
            "override": bool(override) if override is not None else False,
        }

    def _derived_idempotency(ws_id, action, target, req_obj):
        b = json.dumps(
            {"workspace_id": ws_id, "action": action, "target": target, "request": req_obj},
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
        return action + ":" + hashlib.sha256(b).hexdigest()

    # Validate required types/formats (relax: host_id may be any string; only validate ULID if it looks like ddres_...)
    if not _is_ulid("ddws", workspace_id):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid workspace_id format", "field": "workspace_id"})
        return _err("VALIDATION_ERROR", "Invalid workspace_id format", field="workspace_id")
    if not _is_ulid("ddconn", connection_id):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid connection_id format", "field": "connection_id"})
        return _err("VALIDATION_ERROR", "Invalid connection_id format", field="connection_id")
    if not isinstance(idempotency_key, str) or not idempotency_key:
        _log("error", error={"code": "VALIDATION_ERROR", "message": "idempotency_key is required", "field": "idempotency_key"})
        return _err("VALIDATION_ERROR", "idempotency_key is required", field="idempotency_key")
    if host_id is not None and not isinstance(host_id, str):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "host_id must be a string", "field": "host_id"})
        return _err("VALIDATION_ERROR", "host_id must be a string", field="host_id")
    if datadog_host_id is not None and not isinstance(datadog_host_id, str):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "datadog_host_id must be a string", "field": "datadog_host_id"})
        return _err("VALIDATION_ERROR", "datadog_host_id must be a string", field="datadog_host_id")
    if message is not None and not isinstance(message, str):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "message must be a string", "field": "message"})
        return _err("VALIDATION_ERROR", "message must be a string", field="message")
    if override is not None and not isinstance(override, bool):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "override must be a boolean", "field": "override"})
        return _err("VALIDATION_ERROR", "override must be a boolean", field="override")

    dt_end, dt_err = _parse_dt(end, "end")
    if dt_err:
        _log("error", error=dt_err["error"])
        return dt_err

    # Resolve workspace + active connection in same workspace (must use requested connection_id)
    workspaces = _load("workspaces.json")
    if isinstance(workspaces, dict) and "rows" in workspaces:
        workspaces = workspaces.get("data", []) or []
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws or ws.get("status") != "active":
        _log("error", error={"code": "UNAUTHORIZED", "message": "Workspace not accessible"})
        return _err("UNAUTHORIZED", "Workspace not accessible")

    conns = _load("datadog_connections.json")
    if isinstance(conns, dict) and "rows" in conns:
        conns = conns.get("data", []) or []
    if not isinstance(conns, list):
        conns = []
    conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == connection_id and c.get("workspace_id") == workspace_id), None)
    if not conn:
        _log("error", error={"code": "NOT_FOUND", "message": "Datadog connection not found", "field": "connection_id"}, resolved_connection_id=connection_id)
        return _err("NOT_FOUND", "Datadog connection not found", field="connection_id")
    if conn.get("status") != "active":
        _log("error", error={"code": "INVALID_TRANSITION", "message": "Datadog connection is not active", "field": "connection_id"}, resolved_connection_id=connection_id)
        return _err("INVALID_TRANSITION", "Datadog connection is not active", field="connection_id")

    # Resolve target host (prefer host_id if it points to a host resource; otherwise use datadog_host_id as identifier)
    resources = _load("dd_resources.json")
    if isinstance(resources, dict) and "rows" in resources:
        resources = resources.get("data", []) or []
    if not isinstance(resources, list):
        resources = []

    target_datadog_id = None
    target_resource = None

    if isinstance(host_id, str) and host_id:
        # Only enforce format if it claims to be ddres_..., but accept arbitrary strings (audit requires relaxation).
        if host_id.startswith("ddres_") and not _is_ulid("ddres", host_id):
            _log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid host_id format", "field": "host_id"}, resolved_connection_id=connection_id)
            return _err("VALIDATION_ERROR", "Invalid host_id format", field="host_id")
        if _is_ulid("ddres", host_id):
            r = next((x for x in resources if isinstance(x, dict) and x.get("id") == host_id), None)
            if r:
                if r.get("workspace_id") != workspace_id:
                    _log("error", error={"code": "CONFLICT", "message": "host_id belongs to a different workspace", "field": "host_id"}, resolved_connection_id=connection_id)
                    return _err("CONFLICT", "host_id belongs to a different workspace", field="host_id")
                if r.get("connection_id") != connection_id:
                    _log("error", error={"code": "CONFLICT", "message": "host_id belongs to a different connection", "field": "host_id"}, resolved_connection_id=connection_id)
                    return _err("CONFLICT", "host_id belongs to a different connection", field="host_id")
                if r.get("resource_type") != "host":
                    _log("error", error={"code": "VALIDATION_ERROR", "message": "host_id must refer to a host resource", "field": "host_id"}, resolved_connection_id=connection_id)
                    return _err("VALIDATION_ERROR", "host_id must refer to a host resource", field="host_id")
                target_resource = r
                target_datadog_id = r.get("datadog_id")

    if not target_datadog_id:
        if not isinstance(datadog_host_id, str) or not datadog_host_id:
            _log("error", error={"code": "VALIDATION_ERROR", "message": "Either host_id (existing cached host) or datadog_host_id is required", "field": "datadog_host_id"}, resolved_connection_id=connection_id)
            return _err("VALIDATION_ERROR", "Either host_id (existing cached host) or datadog_host_id is required", field="datadog_host_id")
        target_datadog_id = datadog_host_id

    # Idempotency and job creation (unique(workspace_id, idempotency_key))
    jobs = _load("dd_mutation_jobs.json")
    if isinstance(jobs, dict) and "rows" in jobs:
        jobs = jobs.get("data", []) or []
    if not isinstance(jobs, list):
        jobs = []

    normalized_req = _normalize_request()
    derived_key = _derived_idempotency(workspace_id, "mute_host", target_datadog_id, normalized_req)

    # Use client-provided idempotency_key as the uniqueness key, but also persist derived_key in request for traceability.
    existing = next((j for j in jobs if isinstance(j, dict) and j.get("workspace_id") == workspace_id and j.get("idempotency_key") == idempotency_key), None)
    if existing:
        # If existing job refers to a different action/target, that's a conflict.
        if existing.get("action") != "mute_host":
            _log("error", error={"code": "CONFLICT", "message": "idempotency_key already used for a different action", "field": "idempotency_key"}, resolved_connection_id=connection_id)
            return _err("CONFLICT", "idempotency_key already used for a different action", field="idempotency_key")
        if existing.get("connection_id") != connection_id:
            _log("error", error={"code": "CONFLICT", "message": "idempotency_key already used with a different connection", "field": "idempotency_key"}, resolved_connection_id=connection_id)
            return _err("CONFLICT", "idempotency_key already used with a different connection", field="idempotency_key")
        # Safe retry: return existing job as-is (especially when running/succeeded)
        _log("ok", resolved_connection_id=connection_id)
        return {"mutation_job": existing}

    # Rate limit check: per-connection outbound calls per minute (based on request_logs)
    rate_per_min = conn.get("rate_limit_per_minute")
    if not isinstance(rate_per_min, int) or rate_per_min < 1:
        rate_per_min = 60
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    window_start = _now - datetime.timedelta(seconds=60)
    recent_calls = 0
    for l in logs:
        if not isinstance(l, dict):
            continue
        if l.get("connection_id") != connection_id:
            continue
        if l.get("endpoint") not in ("mute_host", "unmute_host", "schedule_downtime", "cancel_downtime", "get_metrics", "get_logs", "list_traces", "get_active_hosts_count", "get_incident", "get_monitor", "get_dashboard"):
            continue
        ts = l.get("timestamp")
        try:
            if isinstance(ts, str):
                tss = ts[:-1] + "+00:00" if ts.endswith("Z") else ts
                tdt = datetime.datetime.fromisoformat(tss)
                if tdt.tzinfo is None:
                    tdt = tdt.replace(tzinfo=datetime.timezone.utc)
                tdt = tdt.astimezone(datetime.timezone.utc)
            elif isinstance(ts, datetime.datetime):
                tdt = ts
            else:
                continue
        except ValueError:
            continue
        if tdt >= window_start:
            recent_calls += 1
    if recent_calls >= rate_per_min:
        # Create job but fail it without "calling Datadog"
        jid = _gen_id("ddjob")
        now_iso = _iso(_now)
        job = {
            "id": jid,
            "workspace_id": workspace_id,
            "connection_id": connection_id,
            "action": "mute_host",
            "status": "failed",
            "idempotency_key": idempotency_key,
            "target_resource_id": target_resource.get("id") if isinstance(target_resource, dict) else None,
            "target_datadog_id": target_datadog_id,
            "request": {"derived_idempotency_key": derived_key, **normalized_req},
            "result": None,
            "http_status": 429,
            "error": {"code": "RATE_LIMIT", "message": "Rate limit exceeded for connection"},
            "requested_at": now_iso,
            "started_at": None,
            "finished_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        jobs.append(job)
        _save("dd_mutation_jobs.json", jobs)
        _log("error", error=job["error"], resolved_connection_id=connection_id)
        return _err("RATE_LIMIT", "Rate limit exceeded for connection")

    # Create job and mark succeeded immediately (offline implementation), respecting transitions
    jid = _gen_id("ddjob")
    now_iso = _iso(_now)
    job = {
        "id": jid,
        "workspace_id": workspace_id,
        "connection_id": connection_id,
        "action": "mute_host",
        "status": "queued",
        "idempotency_key": idempotency_key,
        "target_resource_id": target_resource.get("id") if isinstance(target_resource, dict) else None,
        "target_datadog_id": target_datadog_id,
        "request": {"derived_idempotency_key": derived_key, **normalized_req},
        "result": None,
        "http_status": None,
        "error": None,
        "requested_at": now_iso,
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    jobs.append(job)
    _save("dd_mutation_jobs.json", jobs)

    # Progress queued -> running -> succeeded
    job["status"] = "running"
    job["started_at"] = now_iso
    job["updated_at"] = now_iso

    # Upsert host resource on success
    # Find by unique(workspace_id, resource_type, datadog_id)
    host_row = next((x for x in resources if isinstance(x, dict) and x.get("workspace_id") == workspace_id and x.get("resource_type") == "host" and x.get("datadog_id") == target_datadog_id), None)
    if host_row and host_row.get("connection_id") != connection_id:
        _log("error", error={"code": "CONFLICT", "message": "Cached host belongs to different connection", "field": "datadog_host_id"}, resolved_connection_id=connection_id)
        # Persist failed job
        job["status"] = "failed"
        job["http_status"] = 409
        job["error"] = {"code": "CONFLICT", "message": "Cached host belongs to different connection"}
        job["finished_at"] = now_iso
        job["updated_at"] = now_iso
        _save("dd_mutation_jobs.json", jobs)
        return _err("CONFLICT", "Cached host belongs to different connection", field="datadog_host_id")

    if not host_row:
        host_row = {
            "id": _gen_id("ddres"),
            "workspace_id": workspace_id,
            "connection_id": connection_id,
            "resource_type": "host",
            "datadog_id": target_datadog_id,
            "name": None,
            "status": "muted",
            "tags": None,
            "attributes": None,
            "muted_until": _iso(dt_end),
            "last_seen_at": None,
            "synced_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        resources.append(host_row)
    else:
        # transition: unknown/active->muted, muted stays muted, deleted cannot be changed
        if host_row.get("status") == "deleted":
            _log("error", error={"code": "INVALID_TRANSITION", "message": "Cannot mute a deleted host", "field": "host_id"}, resolved_connection_id=connection_id)
            job["status"] = "failed"
            job["http_status"] = 409
            job["error"] = {"code": "INVALID_TRANSITION", "message": "Cannot mute a deleted host"}
            job["finished_at"] = now_iso
            job["updated_at"] = now_iso
            _save("dd_mutation_jobs.json", jobs)
            return _err("INVALID_TRANSITION", "Cannot mute a deleted host", field="host_id")
        host_row["status"] = "muted"
        host_row["muted_until"] = _iso(dt_end)
        host_row["synced_at"] = now_iso
        host_row["updated_at"] = now_iso

    _save("dd_resources.json", resources)

    job["status"] = "succeeded"
    job["http_status"] = 200
    job["result"] = {"muted": True, "host": {"datadog_id": target_datadog_id, "muted_until": _iso(dt_end)}}
    job["finished_at"] = now_iso
    job["updated_at"] = now_iso
    _save("dd_mutation_jobs.json", jobs)

    _log("ok", resolved_connection_id=connection_id)
    return {"mutation_job": job, "resource": host_row}

def unmute_host(workspace_id, connection_id, idempotency_key, host_id=None, datadog_host_id=None, **_extra):
    import json, os, datetime, time, re, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0395000" if __import__("os").path.isdir("./environment_mix/0395000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _new_req_id():
        return "req_" + base64.b32encode(os.urandom(16)).decode("ascii").rstrip("=").lower()

    def _log(status, error=None, cost_units=0, resolved_connection_id=None, mutation_job_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_req_id(),
            "endpoint": "unmute_host",
            "workspace_id": workspace_id,
            "connection_id": resolved_connection_id if resolved_connection_id is not None else connection_id,
            "credential_id": None,
            "status": status,
            "error": error,
            "cost_units": cost_units,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _iso(datetime.datetime.now(datetime.timezone.utc)),
            "mutation_job_id": mutation_job_id,
        })
        _save("request_logs.json", logs)

    def _is_ulid(prefix, v):
        return isinstance(v, str) and re.match(r"^" + re.escape(prefix) + r"_[0-9A-HJKMNP-TV-Z]{26}$", v) is not None

    def _gen_id(prefix):
        return prefix + "_" + base64.b32encode(os.urandom(16)).decode("ascii").rstrip("=").upper()

    def _stable_idempotency(ws_id, action, target, req_obj):
        # Derived idempotency per business rules; do not require caller key to match format
        b = json.dumps(
            {"workspace_id": ws_id, "action": action, "target": target, "request": req_obj},
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        ).encode("utf-8")
        return action + ":" + hashlib.sha256(b).hexdigest()

    def _parse_iso(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    # ---- Validate inputs (relax where parameter schema allows) ----
    if not _is_ulid("ddws", workspace_id):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid workspace_id format", "field": "workspace_id"})
        return _err("VALIDATION_ERROR", "Invalid workspace_id format", field="workspace_id")
    if not _is_ulid("ddconn", connection_id):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid connection_id format", "field": "connection_id"})
        return _err("VALIDATION_ERROR", "Invalid connection_id format", field="connection_id")
    if not isinstance(idempotency_key, str) or not idempotency_key:
        _log("error", error={"code": "VALIDATION_ERROR", "message": "idempotency_key is required", "field": "idempotency_key"})
        return _err("VALIDATION_ERROR", "idempotency_key is required", field="idempotency_key")
    if host_id is not None and not _is_ulid("ddres", host_id):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid host_id format", "field": "host_id"})
        return _err("VALIDATION_ERROR", "Invalid host_id format", field="host_id")
    if datadog_host_id is not None and (not isinstance(datadog_host_id, str) or not datadog_host_id):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "datadog_host_id must be a non-empty string when provided", "field": "datadog_host_id"})
        return _err("VALIDATION_ERROR", "datadog_host_id must be a non-empty string when provided", field="datadog_host_id")
    if host_id is None and (datadog_host_id is None or datadog_host_id == ""):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Either host_id or datadog_host_id is required", "field": "datadog_host_id"})
        return _err("VALIDATION_ERROR", "Either host_id or datadog_host_id is required", field="datadog_host_id")

    # ---- Resolve workspace + active connection (must search for a working combination) ----
    workspaces = _load("workspaces.json")
    if isinstance(workspaces, dict) and isinstance(workspaces.get("rows"), list):
        workspaces = workspaces["rows"]
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _log("error", error={"code": "NOT_FOUND", "message": "Workspace not found", "field": "workspace_id"})
        return _err("NOT_FOUND", "Workspace not found", field="workspace_id")
    if ws.get("status") == "deleted":
        _log("error", error={"code": "UNAUTHORIZED", "message": "Workspace is deleted"})
        return _err("UNAUTHORIZED", "Workspace is deleted")
    if ws.get("status") != "active":
        _log("error", error={"code": "UNAUTHORIZED", "message": "Workspace is not active"})
        return _err("UNAUTHORIZED", "Workspace is not active")

    connections = _load("datadog_connections.json")
    if isinstance(connections, dict) and isinstance(connections.get("rows"), list):
        connections = connections["rows"]
    if not isinstance(connections, list):
        connections = []
    conn = next((c for c in connections if isinstance(c, dict) and c.get("id") == connection_id and c.get("workspace_id") == workspace_id), None)
    if not conn:
        # Search for any active connection in this workspace; but if the caller specified one, this is a NOT_FOUND on that id.
        _log("error", error={"code": "NOT_FOUND", "message": "Datadog connection not found in workspace", "field": "connection_id"})
        return _err("NOT_FOUND", "Datadog connection not found in workspace", field="connection_id")
    if conn.get("status") != "active":
        _log("error", error={"code": "UNAUTHORIZED", "message": "Datadog connection is not active", "field": "connection_id"}, resolved_connection_id=connection_id)
        return _err("UNAUTHORIZED", "Datadog connection is not active", field="connection_id")

    # ---- Resolve target host identifier ----
    resources = _load("dd_resources.json")
    if isinstance(resources, dict) and isinstance(resources.get("rows"), list):
        resources = resources["rows"]
    if not isinstance(resources, list):
        resources = []

    target_host_datadog_id = None
    target_resource_row = None

    if host_id is not None:
        r = next((x for x in resources if isinstance(x, dict) and x.get("id") == host_id), None)
        if not r:
            _log("error", error={"code": "NOT_FOUND", "message": "Host resource not found", "field": "host_id"}, resolved_connection_id=connection_id)
            return _err("NOT_FOUND", "Host resource not found", field="host_id")
        if r.get("workspace_id") != workspace_id:
            _log("error", error={"code": "CONFLICT", "message": "host_id belongs to a different workspace", "field": "host_id"}, resolved_connection_id=connection_id)
            return _err("CONFLICT", "host_id belongs to a different workspace", field="host_id")
        if r.get("connection_id") != connection_id:
            _log("error", error={"code": "CONFLICT", "message": "host_id belongs to a different connection", "field": "host_id"}, resolved_connection_id=connection_id)
            return _err("CONFLICT", "host_id belongs to a different connection", field="host_id")
        if r.get("resource_type") != "host":
            _log("error", error={"code": "VALIDATION_ERROR", "message": "host_id must refer to a host resource", "field": "host_id"}, resolved_connection_id=connection_id)
            return _err("VALIDATION_ERROR", "host_id must refer to a host resource", field="host_id")
        target_resource_row = r
        target_host_datadog_id = r.get("datadog_id")
    else:
        target_host_datadog_id = datadog_host_id

    if not isinstance(target_host_datadog_id, str) or not target_host_datadog_id:
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Unable to resolve host identifier", "field": "datadog_host_id"}, resolved_connection_id=connection_id)
        return _err("VALIDATION_ERROR", "Unable to resolve host identifier", field="datadog_host_id")

    # ---- Idempotency: derive stable key, do not trust caller key ----
    action = "unmute_host"
    normalized_request = {"host": target_host_datadog_id}
    derived_key = _stable_idempotency(workspace_id, action, target_host_datadog_id, normalized_request)

    jobs = _load("dd_mutation_jobs.json")
    if isinstance(jobs, dict) and isinstance(jobs.get("rows"), list):
        jobs = jobs["rows"]
    if not isinstance(jobs, list):
        jobs = []

    existing = next((j for j in jobs if isinstance(j, dict) and j.get("workspace_id") == workspace_id and j.get("idempotency_key") == derived_key), None)
    if existing:
        # If succeeded or still in-flight, return existing (safe retry)
        _log("ok", resolved_connection_id=connection_id, mutation_job_id=existing.get("id"), cost_units=0)
        return {"mutation_job": existing}

    # ---- Rate limit enforcement (per-connection per-minute) ----
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    window_start = _now - datetime.timedelta(seconds=60)
    calls_last_min = 0
    for e in logs:
        if not isinstance(e, dict):
            continue
        if e.get("connection_id") != connection_id:
            continue
        if e.get("status") != "ok":
            continue
        if e.get("cost_units") is None:
            continue
        if int(e.get("cost_units") or 0) <= 0:
            continue
        ts = _parse_iso(e.get("timestamp"))
        if ts and ts >= window_start:
            calls_last_min += 1
    limit = conn.get("rate_limit_per_minute")
    if not isinstance(limit, int) or limit < 1:
        limit = 60

    # ---- Create queued job ----
    job_id = _gen_id("ddjob")
    job = {
        "id": job_id,
        "workspace_id": workspace_id,
        "connection_id": connection_id,
        "action": action,
        "status": "queued",
        "idempotency_key": derived_key,
        "target_resource_id": target_resource_row.get("id") if isinstance(target_resource_row, dict) else None,
        "target_datadog_id": target_host_datadog_id,
        "request": normalized_request,
        "result": None,
        "http_status": None,
        "error": None,
        "requested_at": _iso(_now),
        "started_at": None,
        "finished_at": None,
        "created_at": _iso(_now),
        "updated_at": _iso(_now),
    }
    jobs.append(job)
    _save("dd_mutation_jobs.json", jobs)

    # If rate-limited: fail job without calling Datadog (offline behavior)
    if calls_last_min >= limit:
        # queued -> running is allowed; but we can fail directly only from running; respect transitions
        job["status"] = "running"
        job["started_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        job["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("dd_mutation_jobs.json", jobs)

        job["status"] = "failed"
        job["error"] = {"code": "RATE_LIMIT", "message": "Rate limit exceeded for connection"}
        job["http_status"] = 429
        job["finished_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        job["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("dd_mutation_jobs.json", jobs)

        _log("error", error={"code": "RATE_LIMIT", "message": "Rate limit exceeded for connection"}, resolved_connection_id=connection_id, mutation_job_id=job_id, cost_units=0)
        return _err("RATE_LIMIT", "Rate limit exceeded for connection")

    # ---- Execute mutation (offline: assume success) ----
    # Progress queued -> running -> succeeded
    job["status"] = "running"
    job["started_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    job["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("dd_mutation_jobs.json", jobs)

    job["status"] = "succeeded"
    job["http_status"] = 200
    job["result"] = {"unmuted": True, "host": target_host_datadog_id}
    job["finished_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    job["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("dd_mutation_jobs.json", jobs)

    # ---- Upsert dd_resources host row ----
    now_iso = _iso(datetime.datetime.now(datetime.timezone.utc))
    host_row = next((x for x in resources if isinstance(x, dict)
                     and x.get("workspace_id") == workspace_id
                     and x.get("connection_id") == connection_id
                     and x.get("resource_type") == "host"
                     and x.get("datadog_id") == target_host_datadog_id), None)
    if host_row:
        host_row["status"] = "active"
        host_row["muted_until"] = None
        host_row["synced_at"] = now_iso
        host_row["updated_at"] = now_iso
    else:
        host_row = {
            "id": _gen_id("ddres"),
            "workspace_id": workspace_id,
            "connection_id": connection_id,
            "resource_type": "host",
            "datadog_id": target_host_datadog_id,
            "name": target_host_datadog_id,
            "status": "active",
            "tags": None,
            "attributes": None,
            "muted_until": None,
            "last_seen_at": None,
            "synced_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        resources.append(host_row)
    _save("dd_resources.json", resources)

    _log("ok", resolved_connection_id=connection_id, mutation_job_id=job_id, cost_units=1)
    return {"mutation_job": job, "host_resource": host_row}

def list_hosts(workspace_id, connection_id, source=None, filter=None, sort=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0395000" if __import__("os").path.isdir("./environment_mix/0395000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    def _log(status, code=None, message=None, meta=None, cred=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{now.strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
            "endpoint": "list_hosts",
            "workspace_id": workspace_id,
            "connection_id": connection_id,
            "credential_id": cred,
            "status": status,
            "error_code": code,
            "error_message": message,
            "meta": meta or {},
            "latency_ms": latency_ms,
            "timestamp": now_iso,
        })
        _save("request_logs.json", logs)

    def _ulid_like(prefix, val):
        if not isinstance(val, str):
            return False
        pat = r"^" + re.escape(prefix) + r"_[0-9A-HJKMNP-TV-Z]{26}$"
        return re.match(pat, val) is not None

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    if not _ulid_like("ddws", workspace_id):
        _log("error", "VALIDATION_ERROR", "Invalid workspace_id format")
        return _err("VALIDATION_ERROR", "Invalid workspace_id format", field="workspace_id")
    if not _ulid_like("ddconn", connection_id):
        _log("error", "VALIDATION_ERROR", "Invalid connection_id format")
        return _err("VALIDATION_ERROR", "Invalid connection_id format", field="connection_id")
    if source is None:
        source = "cache"
    if source not in ("cache", "live"):
        _log("error", "VALIDATION_ERROR", "source must be 'cache' or 'live'")
        return _err("VALIDATION_ERROR", "source must be 'cache' or 'live'", field="source")
    if sort is None:
        sort = "-updated_at"
    if sort not in ("name", "-name", "last_seen_at", "-last_seen_at", "updated_at", "-updated_at"):
        _log("error", "VALIDATION_ERROR", "Invalid sort value")
        return _err("VALIDATION_ERROR", "Invalid sort value", field="sort")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 1000:
        _log("error", "VALIDATION_ERROR", "limit must be between 1 and 1000")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 1000", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        _log("error", "VALIDATION_ERROR", "cursor must be a string")
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")
    if filter is not None and not isinstance(filter, dict):
        _log("error", "VALIDATION_ERROR", "filter must be an object")
        return _err("VALIDATION_ERROR", "filter must be an object", field="filter")

    f_query = None
    f_tags = None
    f_status = None
    f_last_seen_from = None
    f_last_seen_to = None
    if isinstance(filter, dict):
        if "query" in filter:
            if filter["query"] is not None and not isinstance(filter["query"], str):
                _log("error", "VALIDATION_ERROR", "filter.query must be a string")
                return _err("VALIDATION_ERROR", "filter.query must be a string", field="filter.query")
            f_query = (filter.get("query") or "").strip() or None
        if "tags" in filter:
            if filter["tags"] is not None:
                if not isinstance(filter["tags"], list) or not all(isinstance(x, str) for x in filter["tags"]):
                    _log("error", "VALIDATION_ERROR", "filter.tags must be an array of strings")
                    return _err("VALIDATION_ERROR", "filter.tags must be an array of strings", field="filter.tags")
                f_tags = [t for t in (x.strip() for x in filter["tags"]) if t]
        if "status" in filter:
            if filter["status"] is not None and filter["status"] not in ("active", "muted", "resolved", "triggered", "scheduled", "cancelled", "deleted", "unknown"):
                _log("error", "VALIDATION_ERROR", "Invalid filter.status")
                return _err("VALIDATION_ERROR", "Invalid filter.status", field="filter.status")
            f_status = filter.get("status")
        if "last_seen_from" in filter:
            f_last_seen_from = _parse_dt(filter.get("last_seen_from"))
            if filter.get("last_seen_from") is not None and f_last_seen_from is None:
                _log("error", "VALIDATION_ERROR", "filter.last_seen_from must be an ISO 8601 date-time string")
                return _err("VALIDATION_ERROR", "filter.last_seen_from must be an ISO 8601 date-time string", field="filter.last_seen_from")
        if "last_seen_to" in filter:
            f_last_seen_to = _parse_dt(filter.get("last_seen_to"))
            if filter.get("last_seen_to") is not None and f_last_seen_to is None:
                _log("error", "VALIDATION_ERROR", "filter.last_seen_to must be an ISO 8601 date-time string")
                return _err("VALIDATION_ERROR", "filter.last_seen_to must be an ISO 8601 date-time string", field="filter.last_seen_to")
        if f_last_seen_from and f_last_seen_to and f_last_seen_from > f_last_seen_to:
            _log("error", "VALIDATION_ERROR", "filter.last_seen_from must be <= filter.last_seen_to")
            return _err("VALIDATION_ERROR", "filter.last_seen_from must be <= filter.last_seen_to", field="filter.last_seen_from")

    workspaces = _load("workspaces.json")
    conns = _load("datadog_connections.json")
    resources = _load("dd_resources.json")
    if not isinstance(workspaces, list): workspaces = []
    if not isinstance(conns, list): conns = []
    if not isinstance(resources, list): resources = []

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if ws is None or ws.get("status") != "active":
        _log("error", "UNAUTHORIZED", "No active workspace available for this request")
        return _err("UNAUTHORIZED", "No active workspace available for this request")

    conn = next((c for c in conns if c.get("id") == connection_id and c.get("workspace_id") == workspace_id), None)
    if conn is None:
        _log("error", "NOT_FOUND", "Connection not found in workspace")
        return _err("NOT_FOUND", "Connection not found", connection_id=connection_id)
    if conn.get("status") != "active":
        _log("error", "UNAUTHORIZED", "Datadog connection is not active")
        return _err("UNAUTHORIZED", "Datadog connection is not active", connection_status=conn.get("status"))

    # Source=live is not actually callable offline; we behave as cache but log no outbound call.
    # This still produces real results from the datastore.
    rows = [r for r in resources if r.get("workspace_id") == workspace_id and r.get("connection_id") == connection_id and r.get("resource_type") == "host"]

    # Apply cache-based filters
    if f_status is not None:
        rows = [r for r in rows if r.get("status") == f_status]
    if f_tags:
        def has_all_tags(r):
            rt = r.get("tags") or []
            if not isinstance(rt, list):
                return False
            s = set(rt)
            return all(t in s for t in f_tags)
        rows = [r for r in rows if has_all_tags(r)]
    if f_query:
        q = f_query.lower()
        def match_query(r):
            name = (r.get("name") or "").lower()
            did = (r.get("datadog_id") or "").lower()
            tags = r.get("tags") or []
            tagstr = " ".join([t for t in tags if isinstance(t, str)]).lower()
            return (q in name) or (q in did) or (q in tagstr)
        rows = [r for r in rows if match_query(r)]
    if f_last_seen_from is not None:
        def ge_from(r):
            dt = _parse_dt(r.get("last_seen_at"))
            return dt is not None and dt >= f_last_seen_from
        rows = [r for r in rows if ge_from(r)]
    if f_last_seen_to is not None:
        def le_to(r):
            dt = _parse_dt(r.get("last_seen_at"))
            return dt is not None and dt <= f_last_seen_to
        rows = [r for r in rows if le_to(r)]

    # Sort
    reverse = sort.startswith("-")
    key = sort[1:] if reverse else sort

    def key_fn(r):
        v = r.get(key)
        if key in ("updated_at", "last_seen_at"):
            dt = _parse_dt(v)
            return dt or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        if v is None:
            return ""
        return str(v).lower()

    rows.sort(key=key_fn, reverse=reverse)

    # Cursor pagination: cursor = integer offset encoded
    offset = 0
    if cursor:
        try:
            if cursor.startswith("off_"):
                offset = int(cursor.split("_", 1)[1])
            else:
                # allow raw int string
                offset = int(cursor)
            if offset < 0:
                raise ValueError()
        except Exception:
            _log("error", "VALIDATION_ERROR", "Invalid cursor")
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    total = len(rows)
    page = rows[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = f"off_{next_off}" if has_more else None

    _log("ok", meta={"source": source, "returned": len(page), "total": total})

    return {
        "data": page,
        "meta": {
            "source": source,
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
        }
    }

def get_active_hosts_count(workspace_id, connection_id, time_from=None, time_to=None, source=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0395000" if __import__("os").path.isdir("./environment_mix/0395000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    def _log(status, code=None, message=None, meta=None, cred=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{now.strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
            "endpoint": "get_active_hosts_count",
            "workspace_id": workspace_id,
            "connection_id": connection_id,
            "credential_id": cred,
            "status": status,
            "error_code": code,
            "error_message": message,
            "meta": meta or {},
            "latency_ms": latency_ms,
            "timestamp": now_iso,
        })
        _save("request_logs.json", logs)

    def _ulid_like(prefix, val):
        if not isinstance(val, str):
            return False
        pat = r"^" + re.escape(prefix) + r"_[0-9A-HJKMNP-TV-Z]{26}$"
        return re.match(pat, val) is not None

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix, existing_rows):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(datetime.datetime.now(datetime.timezone.utc).timestamp() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ms % 32])
            ms //= 32
        out = list(reversed(out))
        seed = f"{datetime.datetime.now(datetime.timezone.utc).isoformat()}|{len(existing_rows)+1}|{os.getpid()}".encode("utf-8")
        h = hashlib.sha1(seed).digest()
        for b in h:
            out.append(alphabet[b % 32])
            if len(out) >= 26:
                break
        return f"{prefix}_{''.join(out[:26])}"

    if not _ulid_like("ddws", workspace_id):
        _log("error", "VALIDATION_ERROR", "Invalid workspace_id format")
        return _err("VALIDATION_ERROR", "Invalid workspace_id format", field="workspace_id")
    if not _ulid_like("ddconn", connection_id):
        _log("error", "VALIDATION_ERROR", "Invalid connection_id format")
        return _err("VALIDATION_ERROR", "Invalid connection_id format", field="connection_id")
    if source is None:
        source = "cache"
    if source not in ("cache", "live"):
        _log("error", "VALIDATION_ERROR", "source must be 'cache' or 'live'")
        return _err("VALIDATION_ERROR", "source must be 'cache' or 'live'", field="source")

    # Defaults
    tt = _parse_dt(time_to) if time_to is not None else None
    if time_to is not None and tt is None:
        _log("error", "VALIDATION_ERROR", "time_to must be an ISO 8601 date-time string")
        return _err("VALIDATION_ERROR", "time_to must be an ISO 8601 date-time string", field="time_to")
    if tt is None:
        tt = now
    tf = _parse_dt(time_from) if time_from is not None else None
    if time_from is not None and tf is None:
        _log("error", "VALIDATION_ERROR", "time_from must be an ISO 8601 date-time string")
        return _err("VALIDATION_ERROR", "time_from must be an ISO 8601 date-time string", field="time_from")
    if tf is None:
        tf = tt - datetime.timedelta(minutes=5)

    # query_type active_hosts_count allows null times but we still validate ordering when provided/derived
    if tf >= tt:
        _log("error", "VALIDATION_ERROR", "time_from must be before time_to")
        return _err("VALIDATION_ERROR", "time_from must be before time_to", field="time_from")

    workspaces = _load("workspaces.json")
    conns = _load("datadog_connections.json")
    runs = _load("dd_query_runs.json")
    resources = _load("dd_resources.json")
    if not isinstance(workspaces, list): workspaces = []
    if not isinstance(conns, list): conns = []
    if not isinstance(runs, list): runs = []
    if not isinstance(resources, list): resources = []

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if ws is None or ws.get("status") != "active":
        _log("error", "UNAUTHORIZED", "No active workspace available for this request")
        return _err("UNAUTHORIZED", "No active workspace available for this request")

    conn = next((c for c in conns if c.get("id") == connection_id and c.get("workspace_id") == workspace_id), None)
    if conn is None:
        _log("error", "NOT_FOUND", "Connection not found in workspace")
        return _err("NOT_FOUND", "Connection not found", connection_id=connection_id)
    if conn.get("status") != "active":
        _log("error", "UNAUTHORIZED", "Datadog connection is not active")
        return _err("UNAUTHORIZED", "Datadog connection is not active", connection_status=conn.get("status"))

    tf_iso = tf.isoformat()
    tt_iso = tt.isoformat()

    # Cache mode: find most recent succeeded run matching window (exact match) for this connection
    if source == "cache":
        candidates = []
        for r in runs:
            if r.get("workspace_id") != workspace_id or r.get("connection_id") != connection_id:
                continue
            if r.get("query_type") != "active_hosts_count":
                continue
            if r.get("status") != "succeeded":
                continue
            if r.get("time_from") != tf_iso or r.get("time_to") != tt_iso:
                continue
            candidates.append(r)
        candidates.sort(key=lambda x: x.get("finished_at") or x.get("updated_at") or "", reverse=True)
        if candidates:
            best = candidates[0]
            count = None
            if isinstance(best.get("result"), dict):
                count = best["result"].get("count")
            if isinstance(count, int):
                _log("ok", meta={"source": "cache", "run_id": best.get("id")})
                return {"data": {"count": count, "time_from": tf_iso, "time_to": tt_iso, "run_id": best.get("id")}, "meta": {"source": "cache"}}
        # If no cached run, fall through to live computation without outbound call (offline) by deriving from cached hosts
        # This mimics a backend that can compute locally when cache is acceptable.

    # Live mode (offline): create a dd_query_runs row with transitions and compute from dd_resources hosts "active"
    # Rate limit check based on outbound calls per minute; since offline, we still enforce and mark failed without "calling"
    rate = conn.get("rate_limit_per_minute")
    if not isinstance(rate, int) or rate < 1 or rate > 6000:
        _log("error", "VALIDATION_ERROR", "Invalid connection rate_limit_per_minute configuration")
        return _err("VALIDATION_ERROR", "Invalid connection rate_limit_per_minute configuration", connection_id=connection_id)

    # count outbound calls in last minute
    logs = _load("request_logs.json")
    if not isinstance(logs, list): logs = []
    cutoff = now - datetime.timedelta(minutes=1)
    recent_outbound = 0
    for l in logs:
        if l.get("connection_id") != connection_id:
            continue
        if l.get("meta", {}).get("outbound_datadog_call") is not True:
            continue
        ts = l.get("timestamp")
        if not isinstance(ts, str):
            continue
        try:
            if ts.endswith("Z"):
                ts2 = ts[:-1] + "+00:00"
            else:
                ts2 = ts
            dt = datetime.datetime.fromisoformat(ts2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            dt = dt.astimezone(datetime.timezone.utc)
        except Exception:
            continue
        if dt >= cutoff:
            recent_outbound += 1

    run = {
        "id": _new_id("ddqr", runs),
        "workspace_id": workspace_id,
        "connection_id": connection_id,
        "query_type": "active_hosts_count",
        "status": "queued",
        "requested_at": now_iso,
        "started_at": None,
        "finished_at": None,
        "time_from": tf_iso,
        "time_to": tt_iso,
        "request": {"time_from": tf_iso, "time_to": tt_iso},
        "result": None,
        "next_page_cursor": None,
        "error": None,
        "http_status": None,
        "cost_units": 1,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    runs.append(run)
    _save("dd_query_runs.json", runs)

    if recent_outbound >= rate:
        # queued -> running -> failed (rate limit) without outbound
        run["status"] = "running"
        run["started_at"] = now_iso
        run["updated_at"] = now_iso
        _save("dd_query_runs.json", runs)

        fin = datetime.datetime.now(datetime.timezone.utc).isoformat()
        run["status"] = "failed"
        run["finished_at"] = fin
        run["updated_at"] = fin
        run["http_status"] = 429
        run["error"] = {"code": "RATE_LIMIT", "message": "Connection rate limit exceeded"}
        _save("dd_query_runs.json", runs)

        _log("error", "RATE_LIMIT", "Connection rate limit exceeded", meta={"run_id": run["id"], "rate_limit_per_minute": rate, "recent_outbound": recent_outbound})
        return _err("RATE_LIMIT", "Connection rate limit exceeded", connection_id=connection_id, run_id=run["id"])

    # queued -> running
    run["status"] = "running"
    run["started_at"] = now_iso
    run["updated_at"] = now_iso
    _save("dd_query_runs.json", runs)

    # "Outbound" call marker
    _log("ok", meta={"outbound_datadog_call": True, "query_type": "active_hosts_count", "run_id": run["id"]})

    # Compute: count cached hosts last seen within [tf, tt] and not deleted
    def _parse_resource_dt(v):
        return _parse_dt(v) if isinstance(v, str) else None

    count = 0
    for r in resources:
        if r.get("workspace_id") != workspace_id or r.get("connection_id") != connection_id:
            continue
        if r.get("resource_type") != "host":
            continue
        if r.get("status") in ("deleted",):
            continue
        ls = _parse_resource_dt(r.get("last_seen_at"))
        # If last_seen_at missing, treat as not active in window
        if ls is None:
            continue
        if tf <= ls <= tt:
            count += 1

    fin = datetime.datetime.now(datetime.timezone.utc).isoformat()
    run["status"] = "succeeded"
    run["finished_at"] = fin
    run["updated_at"] = fin
    run["http_status"] = 200
    run["result"] = {"count": count, "time_from": tf_iso, "time_to": tt_iso}
    _save("dd_query_runs.json", runs)

    return {"data": {"count": count, "time_from": tf_iso, "time_to": tt_iso, "run_id": run["id"]}, "meta": {"source": source}}

def list_downtimes(workspace_id, connection_id, source=None, filter=None, sort=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, hashlib, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0395000" if __import__("os").path.isdir("./environment_mix/0395000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return dt

    def _parse_dt(s, field_name):
        if s is None:
            return None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field_name} must be an RFC3339 datetime string")
        try:
            # Accept ...Z or offset
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            else:
                dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field_name} must be an RFC3339 datetime string")

    def _record_log(status, credential_id=None, error=None):
        latency_ms = int((time.time() - _t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + base64.b32encode(os.urandom(16)).decode("ascii").rstrip("=").lower(),
            "endpoint": "list_downtimes",
            "workspace_id": workspace_id,
            "connection_id": connection_id,
            "credential_id": credential_id,
            "status": status,
            "error": error,
            "latency_ms": latency_ms,
            "timestamp": _iso(_now),
        })
        _save("request_logs.json", logs)

    def _ulid_ok(v, pat):
        return isinstance(v, str) and re.match(pat, v) is not None

    def _bump_usage(conn_row, units=1):
        usage = _load("usage.json")
        if not isinstance(usage, list):
            usage = []
        found = None
        for r in usage:
            if isinstance(r, dict) and r.get("connection_id") == conn_row["id"]:
                found = r
                break
        if found is None:
            found = {
                "connection_id": conn_row["id"],
                "workspace_id": conn_row["workspace_id"],
                "outbound_calls_total": 0,
                "outbound_calls_by_minute": {}
            }
            usage.append(found)
        found["outbound_calls_total"] = int(found.get("outbound_calls_total") or 0) + int(units)
        minute = _now.strftime("%Y-%m-%dT%H:%MZ")
        bym = found.get("outbound_calls_by_minute")
        if not isinstance(bym, dict):
            bym = {}
            found["outbound_calls_by_minute"] = bym
        bym[minute] = int(bym.get(minute) or 0) + int(units)
        _save("usage.json", usage)

    def _calls_in_last_minute(conn_row):
        usage = _load("usage.json")
        if not isinstance(usage, list):
            return 0
        minute = _now.strftime("%Y-%m-%dT%H:%MZ")
        for r in usage:
            if isinstance(r, dict) and r.get("connection_id") == conn_row["id"]:
                bym = r.get("outbound_calls_by_minute")
                if isinstance(bym, dict):
                    return int(bym.get(minute) or 0)
        return 0

    # Validate inputs
    if not _ulid_ok(workspace_id, r"^ddws_[0-9A-HJKMNP-TV-Z]{26}$"):
        _record_log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid workspace_id"})
        return _err("VALIDATION_ERROR", "Invalid workspace_id")
    if not _ulid_ok(connection_id, r"^ddconn_[0-9A-HJKMNP-TV-Z]{26}$"):
        _record_log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid connection_id"})
        return _err("VALIDATION_ERROR", "Invalid connection_id")

    if source is None:
        source = "cache"
    if source not in ("cache", "live"):
        _record_log("error", error={"code": "VALIDATION_ERROR", "message": "source must be 'cache' or 'live'"})
        return _err("VALIDATION_ERROR", "source must be 'cache' or 'live'")
    if sort is None:
        sort = "-updated_at"
    if sort not in ("created_at", "-created_at", "updated_at", "-updated_at"):
        _record_log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid sort"})
        return _err("VALIDATION_ERROR", "Invalid sort")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 1000:
        _record_log("error", error={"code": "VALIDATION_ERROR", "message": "limit must be an integer between 1 and 1000"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 1000")

    if filter is not None and not isinstance(filter, dict):
        _record_log("error", error={"code": "VALIDATION_ERROR", "message": "filter must be an object"})
        return _err("VALIDATION_ERROR", "filter must be an object")

    f_current_only = False
    f_include_cancelled = False
    f_status = None
    f_time_from = None
    f_time_to = None
    f_tags = None

    if isinstance(filter, dict):
        if "current_only" in filter:
            if not isinstance(filter["current_only"], bool):
                _record_log("error", error={"code": "VALIDATION_ERROR", "message": "filter.current_only must be boolean"})
                return _err("VALIDATION_ERROR", "filter.current_only must be boolean")
            f_current_only = filter["current_only"]
        if "include_cancelled" in filter:
            if not isinstance(filter["include_cancelled"], bool):
                _record_log("error", error={"code": "VALIDATION_ERROR", "message": "filter.include_cancelled must be boolean"})
                return _err("VALIDATION_ERROR", "filter.include_cancelled must be boolean")
            f_include_cancelled = filter["include_cancelled"]
        if "status" in filter and filter["status"] is not None:
            allowed_status = {"active","muted","resolved","triggered","scheduled","cancelled","deleted","unknown"}
            if filter["status"] not in allowed_status:
                _record_log("error", error={"code": "VALIDATION_ERROR", "message": "filter.status is invalid"})
                return _err("VALIDATION_ERROR", "filter.status is invalid")
            f_status = filter["status"]
        if "time_from" in filter and filter["time_from"] is not None:
            f_time_from, e = _parse_dt(filter["time_from"], "filter.time_from")
            if e:
                _record_log("error", error=e["error"])
                return e
        if "time_to" in filter and filter["time_to"] is not None:
            f_time_to, e = _parse_dt(filter["time_to"], "filter.time_to")
            if e:
                _record_log("error", error=e["error"])
                return e
        if "tags" in filter and filter["tags"] is not None:
            if not isinstance(filter["tags"], list) or any(not isinstance(x, str) for x in filter["tags"]):
                _record_log("error", error={"code": "VALIDATION_ERROR", "message": "filter.tags must be an array of strings"})
                return _err("VALIDATION_ERROR", "filter.tags must be an array of strings")
            f_tags = [t for t in filter["tags"] if t.strip() != ""]

    # Resolve workspace + connection (must be active; must belong to workspace)
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _record_log("error", error={"code": "NOT_FOUND", "message": "Workspace not found"})
        return _err("NOT_FOUND", "Workspace not found")
    if ws.get("status") != "active":
        _record_log("error", error={"code": "UNAUTHORIZED", "message": "Workspace is not active"})
        return _err("UNAUTHORIZED", "Workspace is not active")

    conns = _load("datadog_connections.json")
    conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == connection_id), None)
    if not conn or conn.get("workspace_id") != workspace_id:
        _record_log("error", error={"code": "NOT_FOUND", "message": "Datadog connection not found for workspace"})
        return _err("NOT_FOUND", "Datadog connection not found for workspace")
    if conn.get("status") != "active":
        _record_log("error", error={"code": "UNAUTHORIZED", "message": "Datadog connection is not active"})
        return _err("UNAUTHORIZED", "Datadog connection is not active")

    # Cursor handling (cache-based pagination only)
    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            _record_log("error", error={"code": "VALIDATION_ERROR", "message": "cursor must be a string"})
            return _err("VALIDATION_ERROR", "cursor must be a string")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            if not isinstance(payload, dict) or payload.get("v") != 1:
                raise ValueError("bad cursor")
            if payload.get("workspace_id") != workspace_id or payload.get("connection_id") != connection_id or payload.get("resource_type") != "downtime":
                _record_log("error", error={"code": "VALIDATION_ERROR", "message": "cursor does not match request scope"})
                return _err("VALIDATION_ERROR", "cursor does not match request scope")
            start = int(payload.get("offset") or 0)
            if start < 0:
                raise ValueError("bad offset")
        except Exception:
            _record_log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid cursor"})
            return _err("VALIDATION_ERROR", "Invalid cursor")

    # live source: enforce rate limit and create a query_run-like record? Spec doesn't require; we still log request and fail offline.
    if source == "live":
        # Rate limit check
        calls = _calls_in_last_minute(conn)
        if calls + 1 > int(conn.get("rate_limit_per_minute") or 0):
            _record_log("error", credential_id=conn["id"], error={"code": "RATE_LIMIT", "message": "Connection rate limit exceeded"})
            return _err("RATE_LIMIT", "Connection rate limit exceeded", retry_after_seconds=60)
        # Can't call Datadog offline; record a failed attempt without incrementing outbound usage? Real backend would call; we simulate refusal.
        _record_log("error", credential_id=conn["id"], error={"code": "UNAUTHORIZED", "message": "Live Datadog calls are unavailable in this offline datastore"})
        return _err("UNAUTHORIZED", "Live Datadog calls are unavailable in this offline datastore")

    # cache source
    resources = _load("dd_resources.json")
    rows = []
    for r in resources:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id:
            continue
        if r.get("connection_id") != connection_id:
            continue
        if r.get("resource_type") != "downtime":
            continue
        # Enforce constraint: downtime statuses allowed
        if r.get("status") not in ("scheduled", "cancelled", "deleted", "unknown"):
            continue
        if f_status is not None and r.get("status") != f_status:
            continue
        if not f_include_cancelled and r.get("status") == "cancelled":
            continue
        if f_tags is not None:
            rt = r.get("tags") or []
            if not isinstance(rt, list):
                rt = []
            # require all filter tags present
            srt = set([x for x in rt if isinstance(x, str)])
            if any(t not in srt for t in f_tags):
                continue
        # best-effort time overlap using attributes if present
        if f_time_from is not None or f_time_to is not None or f_current_only:
            attrs = r.get("attributes") if isinstance(r.get("attributes"), dict) else {}
            # Accept various names
            def _attr_dt(keys):
                for k in keys:
                    v = attrs.get(k)
                    if isinstance(v, str):
                        dt, e = _parse_dt(v, f"attributes.{k}")
                        if not e:
                            return dt
                    if isinstance(v, (int, float)):
                        try:
                            return datetime.datetime.fromtimestamp(float(v), tz=datetime.timezone.utc)
                        except Exception:
                            pass
                return None
            ds = _attr_dt(["start", "start_time", "start_ts", "start_date"])
            de = _attr_dt(["end", "end_time", "end_ts", "end_date"])
            # If current_only: active at time_to or now. Consider open-ended (de None) as active if ds <= t.
            t = f_time_to or _now
            if f_current_only:
                if ds is not None and ds > t:
                    continue
                if de is not None and de <= t:
                    continue
            # If time_from/time_to: include those overlapping range best-effort
            if f_time_from is not None or f_time_to is not None:
                rng_start = f_time_from
                rng_end = f_time_to
                # overlap check when we have ds/de
                if ds is not None and rng_end is not None and ds > rng_end:
                    continue
                if de is not None and rng_start is not None and de < rng_start:
                    continue
        rows.append(r)

    # sorting
    key_field = sort.lstrip("-")
    desc = sort.startswith("-")
    def _k(r):
        v = r.get(key_field)
        # datetime stored as string; sort lexicographically for ISO8601
        return v or ""
    rows.sort(key=_k, reverse=desc)

    total = len(rows)
    page = rows[start:start + limit]
    has_more = start + limit < total
    next_cursor = None
    if has_more:
        payload = {"v": 1, "workspace_id": workspace_id, "connection_id": connection_id, "resource_type": "downtime", "offset": start + limit}
        raw = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    _record_log("ok", credential_id=conn["id"])
    return {
        "data": page,
        "meta": {
            "source": "cache",
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        }
    }

def schedule_downtime(workspace_id, connection_id, idempotency_key, scope, start, end=None, message=None, timezone=None, monitor_id=None, monitor_tags=None, recurrence=None, **_extra):
    import json, os, datetime, re, time, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0395000" if __import__("os").path.isdir("./environment_mix/0395000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return dt

    def _log(status, error=None, cost_units=0):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + base64.b32encode(os.urandom(16)).decode("ascii").rstrip("=").lower(),
            "endpoint": "schedule_downtime",
            "workspace_id": workspace_id,
            "connection_id": connection_id,
            "credential_id": None,
            "status": status,
            "error": error,
            "cost_units": cost_units,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _iso(_now),
        })
        _save("request_logs.json", logs)

    def _is_ulid(prefix, v):
        return isinstance(v, str) and re.match(r"^" + re.escape(prefix) + r"_[0-9A-HJKMNP-TV-Z]{26}$", v) is not None

    def _parse_dt(s, field):
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a date-time string", field=field)
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} is malformed; expected RFC3339 date-time", field=field)

    def _gen_id(prefix):
        return prefix + "_" + base64.b32encode(os.urandom(16)).decode("ascii").rstrip("=")

    # Validate
    if not _is_ulid("ddws", workspace_id):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid workspace_id format", "field": "workspace_id"})
        return _err("VALIDATION_ERROR", "Invalid workspace_id format", field="workspace_id")
    if not _is_ulid("ddconn", connection_id):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid connection_id format", "field": "connection_id"})
        return _err("VALIDATION_ERROR", "Invalid connection_id format", field="connection_id")
    if not isinstance(idempotency_key, str) or not idempotency_key:
        _log("error", error={"code": "VALIDATION_ERROR", "message": "idempotency_key must be a non-empty string", "field": "idempotency_key"})
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string", field="idempotency_key")
    if not isinstance(scope, list) or len(scope) == 0 or any(not isinstance(s, str) for s in scope):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "scope must be a non-empty array of strings", "field": "scope"})
        return _err("VALIDATION_ERROR", "scope must be a non-empty array of strings", field="scope")
    start_dt, e = _parse_dt(start, "start")
    if e:
        _log("error", error=e["error"])
        return e
    end_dt = None
    if end is not None:
        end_dt, e = _parse_dt(end, "end")
        if e:
            _log("error", error=e["error"])
            return e
        if end_dt <= start_dt:
            er = _err("VALIDATION_ERROR", "end must be after start", field="end")
            _log("error", error=er["error"])
            return er
    if recurrence is not None:
        if not isinstance(recurrence, dict):
            _log("error", error={"code": "VALIDATION_ERROR", "message": "recurrence must be an object", "field": "recurrence"})
            return _err("VALIDATION_ERROR", "recurrence must be an object", field="recurrence")
        if set(recurrence.keys()) - {"type", "period", "week_days", "until_date"}:
            _log("error", error={"code": "VALIDATION_ERROR", "message": "recurrence has unknown fields", "field": "recurrence"})
            return _err("VALIDATION_ERROR", "recurrence has unknown fields", field="recurrence")
        if recurrence.get("type") not in ("days", "weeks", "months", "years"):
            _log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid recurrence.type", "field": "recurrence.type"})
            return _err("VALIDATION_ERROR", "Invalid recurrence.type", field="recurrence.type")
        if not isinstance(recurrence.get("period"), int) or recurrence.get("period") < 1:
            _log("error", error={"code": "VALIDATION_ERROR", "message": "recurrence.period must be >= 1", "field": "recurrence.period"})
            return _err("VALIDATION_ERROR", "recurrence.period must be >= 1", field="recurrence.period")
        if "week_days" in recurrence:
            wd = recurrence.get("week_days")
            if not isinstance(wd, list) or any(d not in ("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun") for d in wd):
                _log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid recurrence.week_days", "field": "recurrence.week_days"})
                return _err("VALIDATION_ERROR", "Invalid recurrence.week_days", field="recurrence.week_days")
        if "until_date" in recurrence and recurrence.get("until_date") is not None:
            ud, e = _parse_dt(recurrence.get("until_date"), "recurrence.until_date")
            if e:
                _log("error", error=e["error"])
                return e

    # Resolve workspace/connection
    workspaces = _load("workspaces.json")
    conns = _load("datadog_connections.json")
    jobs = _load("dd_mutation_jobs.json")
    resources = _load("dd_resources.json")
    if not isinstance(jobs, list):
        jobs = []
    if not isinstance(resources, list):
        resources = []

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None or ws.get("status") == "deleted":
        _log("error", error={"code": "NOT_FOUND", "message": "Workspace not found"})
        return _err("NOT_FOUND", "Workspace not found")

    conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == connection_id and c.get("workspace_id") == workspace_id), None)
    if conn is None:
        _log("error", error={"code": "NOT_FOUND", "message": "Connection not found for workspace"})
        return _err("NOT_FOUND", "Connection not found for workspace")
    if conn.get("status") != "active":
        _log("error", error={"code": "UNAUTHORIZED", "message": "Datadog connection is not active"})
        return _err("UNAUTHORIZED", "Datadog connection is not active")

    req_obj = {
        "scope": scope,
        "start": _iso(start_dt),
        "end": _iso(end_dt) if end_dt else None,
        "message": message,
        "timezone": timezone,
        "monitor_id": monitor_id,
        "monitor_tags": monitor_tags,
        "recurrence": recurrence,
    }
    stable_idem = "idem_" + hashlib.sha256(
        json.dumps({"workspace_id": workspace_id, "action": "schedule_downtime", "target_datadog_id": None, "request": req_obj},
                   sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
    ).hexdigest()

    existing = next((j for j in jobs if isinstance(j, dict)
                     and j.get("workspace_id") == workspace_id
                     and j.get("idempotency_key") == stable_idem), None)
    if existing is not None and existing.get("status") in ("queued", "running", "succeeded"):
        _log("ok", cost_units=1)
        return {"data": existing, "meta": {"reused": True, "stable_idempotency_key": stable_idem}}

    # Rate limit check
    rate = conn.get("rate_limit_per_minute")
    try:
        rate = int(rate)
    except Exception:
        rate = 60
    if rate < 1:
        rate = 1
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    window_start = _now - datetime.timedelta(minutes=1)
    outbound = 0
    for lg in logs:
        if not isinstance(lg, dict):
            continue
        if lg.get("connection_id") != connection_id:
            continue
        ep = lg.get("endpoint")
        if ep in ("get_metrics", "get_logs", "list_traces", "get_active_hosts_count", "mute_host", "unmute_host", "schedule_downtime", "cancel_downtime"):
            ts = lg.get("timestamp")
            if isinstance(ts, str):
                try:
                    ss = ts[:-1] + "+00:00" if ts.endswith("Z") else ts
                    dt = datetime.datetime.fromisoformat(ss)
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=datetime.timezone.utc)
                    dt = dt.astimezone(datetime.timezone.utc)
                    if dt >= window_start:
                        outbound += 1
                except ValueError:
                    pass

    job_id = _gen_id("ddjob")
    requested_at = _iso(_now)
    job = {
        "id": job_id,
        "workspace_id": workspace_id,
        "connection_id": connection_id,
        "action": "schedule_downtime",
        "status": "queued",
        "idempotency_key": stable_idem,
        "target_resource_id": None,
        "target_datadog_id": None,
        "request": req_obj,
        "result": None,
        "http_status": None,
        "error": None,
        "requested_at": requested_at,
        "started_at": None,
        "finished_at": None,
        "created_at": requested_at,
        "updated_at": requested_at,
    }
    jobs.append(job)
    _save("dd_mutation_jobs.json", jobs)

    if outbound >= rate:
        fail_at = _iso(datetime.datetime.now(datetime.timezone.utc))
        for j in jobs:
            if isinstance(j, dict) and j.get("id") == job_id:
                j["status"] = "failed"
                j["started_at"] = requested_at
                j["finished_at"] = fail_at
                j["error"] = {"code": "RATE_LIMIT", "message": "Rate limit exceeded for connection"}
                j["updated_at"] = fail_at
                break
        _save("dd_mutation_jobs.json", jobs)
        _log("error", error={"code": "RATE_LIMIT", "message": "Rate limit exceeded for connection"}, cost_units=1)
        return _err("RATE_LIMIT", "Rate limit exceeded for connection")

    # Offline success and upsert downtime resource with a generated Datadog id
    started_at = _iso(datetime.datetime.now(datetime.timezone.utc))
    for j in jobs:
        if isinstance(j, dict) and j.get("id") == job_id:
            j["status"] = "running"
            j["started_at"] = started_at
            j["updated_at"] = started_at
            break
    _save("dd_mutation_jobs.json", jobs)

    datadog_id = "dt_" + base64.b32encode(os.urandom(10)).decode("ascii").rstrip("=").lower()
    finished_at = _iso(datetime.datetime.now(datetime.timezone.utc))
    result = {"downtime_id": datadog_id, "status": "scheduled"}

    for j in jobs:
        if isinstance(j, dict) and j.get("id") == job_id:
            j["status"] = "succeeded"
            j["finished_at"] = finished_at
            j["result"] = result
            j["http_status"] = 200
            j["target_datadog_id"] = datadog_id
            j["updated_at"] = finished_at
            break
    _save("dd_mutation_jobs.json", jobs)

    # Upsert dd_resources downtime
    now_iso = finished_at
    dt_row = next((r for r in resources if isinstance(r, dict)
                   and r.get("workspace_id") == workspace_id
                   and r.get("connection_id") == connection_id
                   and r.get("resource_type") == "downtime"
                   and str(r.get("datadog_id")) == datadog_id), None)
    if dt_row is None:
        dt_row = {
            "id": _gen_id("ddres"),
            "workspace_id": workspace_id,
            "connection_id": connection_id,
            "resource_type": "downtime",
            "datadog_id": datadog_id,
            "name": None,
            "status": "scheduled",
            "tags": scope,
            "attributes": req_obj,
            "muted_until": None,
            "last_seen_at": None,
            "synced_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        resources.append(dt_row)
    else:
        dt_row["status"] = "scheduled"
        dt_row["synced_at"] = now_iso
        dt_row["updated_at"] = now_iso
        dt_row["attributes"] = req_obj
    _save("dd_resources.json", resources)

    # Back-reference job.target_resource_id if possible
    for j in jobs:
        if isinstance(j, dict) and j.get("id") == job_id:
            j["target_resource_id"] = dt_row.get("id")
            j["updated_at"] = now_iso
            break
    _save("dd_mutation_jobs.json", jobs)

    job_row = next((j for j in jobs if isinstance(j, dict) and j.get("id") == job_id), None)
    _log("ok", cost_units=1)
    return {"data": job_row, "meta": {"reused": False, "stable_idempotency_key": stable_idem, "downtime_resource_id": dt_row.get("id")}}

def cancel_downtime(workspace_id, connection_id, downtime_id=None, datadog_downtime_id=None, idempotency_key=None, **_extra):
    import json, os, datetime, time, re, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0395000" if __import__("os").path.isdir("./environment_mix/0395000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_iso(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _new_req_id():
        return "req_" + base64.b32encode(os.urandom(16)).decode("ascii").rstrip("=").lower()

    def _log(status, error=None, cost_units=0, resolved_connection_id=None, mutation_job_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_req_id(),
            "endpoint": "cancel_downtime",
            "workspace_id": workspace_id,
            "connection_id": resolved_connection_id if resolved_connection_id is not None else connection_id,
            "credential_id": None,
            "status": status,
            "error": error,
            "cost_units": cost_units,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _iso(datetime.datetime.now(datetime.timezone.utc)),
            "mutation_job_id": mutation_job_id,
        })
        _save("request_logs.json", logs)

    def _is_ulid(prefix, v):
        return isinstance(v, str) and re.match(r"^" + re.escape(prefix) + r"_[0-9A-HJKMNP-TV-Z]{26}$", v) is not None

    def _gen_id(prefix):
        return prefix + "_" + base64.b32encode(os.urandom(16)).decode("ascii").rstrip("=").upper()

    def _stable_idempotency(ws_id, action, target, req_obj):
        b = json.dumps(
            {"workspace_id": ws_id, "action": action, "target": target, "request": req_obj},
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        ).encode("utf-8")
        return action + ":" + hashlib.sha256(b).hexdigest()

    # ---- Validate inputs (accept any string idempotency_key; tool requires it) ----
    if not _is_ulid("ddws", workspace_id):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid workspace_id format", "field": "workspace_id"})
        return _err("VALIDATION_ERROR", "Invalid workspace_id format", field="workspace_id")
    if not _is_ulid("ddconn", connection_id):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid connection_id format", "field": "connection_id"})
        return _err("VALIDATION_ERROR", "Invalid connection_id format", field="connection_id")
    if not isinstance(idempotency_key, str) or not idempotency_key:
        _log("error", error={"code": "VALIDATION_ERROR", "message": "idempotency_key is required", "field": "idempotency_key"})
        return _err("VALIDATION_ERROR", "idempotency_key is required", field="idempotency_key")
    if downtime_id is not None and not _is_ulid("ddres", downtime_id):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid downtime_id format", "field": "downtime_id"})
        return _err("VALIDATION_ERROR", "Invalid downtime_id format", field="downtime_id")
    if datadog_downtime_id is not None and (not isinstance(datadog_downtime_id, str) or not datadog_downtime_id):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "datadog_downtime_id must be a non-empty string when provided", "field": "datadog_downtime_id"})
        return _err("VALIDATION_ERROR", "datadog_downtime_id must be a non-empty string when provided", field="datadog_downtime_id")
    if downtime_id is None and (datadog_downtime_id is None or datadog_downtime_id == ""):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Either downtime_id or datadog_downtime_id is required", "field": "datadog_downtime_id"})
        return _err("VALIDATION_ERROR", "Either downtime_id or datadog_downtime_id is required", field="datadog_downtime_id")

    # ---- Resolve workspace + active connection ----
    workspaces = _load("workspaces.json")
    if isinstance(workspaces, dict) and isinstance(workspaces.get("rows"), list):
        workspaces = workspaces["rows"]
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _log("error", error={"code": "NOT_FOUND", "message": "Workspace not found", "field": "workspace_id"})
        return _err("NOT_FOUND", "Workspace not found", field="workspace_id")
    if ws.get("status") == "deleted":
        _log("error", error={"code": "UNAUTHORIZED", "message": "Workspace is deleted"})
        return _err("UNAUTHORIZED", "Workspace is deleted")
    if ws.get("status") != "active":
        _log("error", error={"code": "UNAUTHORIZED", "message": "Workspace is not active"})
        return _err("UNAUTHORIZED", "Workspace is not active")

    connections = _load("datadog_connections.json")
    if isinstance(connections, dict) and isinstance(connections.get("rows"), list):
        connections = connections["rows"]
    if not isinstance(connections, list):
        connections = []
    conn = next((c for c in connections if isinstance(c, dict) and c.get("id") == connection_id and c.get("workspace_id") == workspace_id), None)
    if not conn:
        _log("error", error={"code": "NOT_FOUND", "message": "Datadog connection not found in workspace", "field": "connection_id"})
        return _err("NOT_FOUND", "Datadog connection not found in workspace", field="connection_id")
    if conn.get("status") != "active":
        _log("error", error={"code": "UNAUTHORIZED", "message": "Datadog connection is not active", "field": "connection_id"}, resolved_connection_id=connection_id)
        return _err("UNAUTHORIZED", "Datadog connection is not active", field="connection_id")

    # ---- Resolve target downtime datadog id, and optionally cached resource row ----
    resources = _load("dd_resources.json")
    if isinstance(resources, dict) and isinstance(resources.get("rows"), list):
        resources = resources["rows"]
    if not isinstance(resources, list):
        resources = []

    target_dd_id = None
    downtime_row = None

    if downtime_id is not None:
        r = next((x for x in resources if isinstance(x, dict) and x.get("id") == downtime_id), None)
        if not r:
            _log("error", error={"code": "NOT_FOUND", "message": "Downtime resource not found", "field": "downtime_id"}, resolved_connection_id=connection_id)
            return _err("NOT_FOUND", "Downtime resource not found", field="downtime_id")
        if r.get("workspace_id") != workspace_id:
            _log("error", error={"code": "CONFLICT", "message": "downtime_id belongs to a different workspace", "field": "downtime_id"}, resolved_connection_id=connection_id)
            return _err("CONFLICT", "downtime_id belongs to a different workspace", field="downtime_id")
        if r.get("connection_id") != connection_id:
            _log("error", error={"code": "CONFLICT", "message": "downtime_id belongs to a different connection", "field": "downtime_id"}, resolved_connection_id=connection_id)
            return _err("CONFLICT", "downtime_id belongs to a different connection", field="downtime_id")
        if r.get("resource_type") != "downtime":
            _log("error", error={"code": "VALIDATION_ERROR", "message": "downtime_id must refer to a downtime resource", "field": "downtime_id"}, resolved_connection_id=connection_id)
            return _err("VALIDATION_ERROR", "downtime_id must refer to a downtime resource", field="downtime_id")
        downtime_row = r
        target_dd_id = r.get("datadog_id")
    else:
        target_dd_id = datadog_downtime_id
        downtime_row = next((x for x in resources if isinstance(x, dict)
                             and x.get("workspace_id") == workspace_id
                             and x.get("connection_id") == connection_id
                             and x.get("resource_type") == "downtime"
                             and x.get("datadog_id") == target_dd_id), None)

    if not isinstance(target_dd_id, str) or not target_dd_id:
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Unable to resolve Datadog downtime identifier", "field": "datadog_downtime_id"}, resolved_connection_id=connection_id)
        return _err("VALIDATION_ERROR", "Unable to resolve Datadog downtime identifier", field="datadog_downtime_id")

    action = "cancel_downtime"
    normalized_request = {"downtime": target_dd_id}
    derived_key = _stable_idempotency(workspace_id, action, target_dd_id, normalized_request)

    jobs = _load("dd_mutation_jobs.json")
    if isinstance(jobs, dict) and isinstance(jobs.get("rows"), list):
        jobs = jobs["rows"]
    if not isinstance(jobs, list):
        jobs = []

    existing = next((j for j in jobs if isinstance(j, dict) and j.get("workspace_id") == workspace_id and j.get("idempotency_key") == derived_key), None)
    if existing:
        _log("ok", resolved_connection_id=connection_id, mutation_job_id=existing.get("id"), cost_units=0)
        return {"mutation_job": existing, "downtime_resource": downtime_row}

    # Idempotent success if already cancelled in cache (still create a succeeded job? real systems often do).
    # Here: create a job and mark succeeded without outbound call/cost.
    already_cancelled = isinstance(downtime_row, dict) and downtime_row.get("status") == "cancelled"

    # ---- Rate limit enforcement ----
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    window_start = _now - datetime.timedelta(seconds=60)
    calls_last_min = 0
    for e in logs:
        if not isinstance(e, dict):
            continue
        if e.get("connection_id") != connection_id:
            continue
        if e.get("status") != "ok":
            continue
        if int(e.get("cost_units") or 0) <= 0:
            continue
        ts = _parse_iso(e.get("timestamp"))
        if ts and ts >= window_start:
            calls_last_min += 1
    limit = conn.get("rate_limit_per_minute")
    if not isinstance(limit, int) or limit < 1:
        limit = 60

    job_id = _gen_id("ddjob")
    job = {
        "id": job_id,
        "workspace_id": workspace_id,
        "connection_id": connection_id,
        "action": action,
        "status": "queued",
        "idempotency_key": derived_key,
        "target_resource_id": downtime_row.get("id") if isinstance(downtime_row, dict) else None,
        "target_datadog_id": target_dd_id,
        "request": normalized_request,
        "result": None,
        "http_status": None,
        "error": None,
        "requested_at": _iso(_now),
        "started_at": None,
        "finished_at": None,
        "created_at": _iso(_now),
        "updated_at": _iso(_now),
    }
    jobs.append(job)
    _save("dd_mutation_jobs.json", jobs)

    if already_cancelled:
        job["status"] = "running"
        job["started_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        job["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("dd_mutation_jobs.json", jobs)

        job["status"] = "succeeded"
        job["http_status"] = 200
        job["result"] = {"cancelled": True, "idempotent": True, "downtime": target_dd_id}
        job["finished_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        job["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("dd_mutation_jobs.json", jobs)

        _log("ok", resolved_connection_id=connection_id, mutation_job_id=job_id, cost_units=0)
        return {"mutation_job": job, "downtime_resource": downtime_row}

    if calls_last_min >= limit:
        job["status"] = "running"
        job["started_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        job["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("dd_mutation_jobs.json", jobs)

        job["status"] = "failed"
        job["error"] = {"code": "RATE_LIMIT", "message": "Rate limit exceeded for connection"}
        job["http_status"] = 429
        job["finished_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        job["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("dd_mutation_jobs.json", jobs)

        _log("error", error={"code": "RATE_LIMIT", "message": "Rate limit exceeded for connection"}, resolved_connection_id=connection_id, mutation_job_id=job_id, cost_units=0)
        return _err("RATE_LIMIT", "Rate limit exceeded for connection")

    # ---- Execute mutation (offline: assume success; if downtime not in cache, still succeed but no resource to update) ----
    job["status"] = "running"
    job["started_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    job["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("dd_mutation_jobs.json", jobs)

    job["status"] = "succeeded"
    job["http_status"] = 200
    job["result"] = {"cancelled": True, "downtime": target_dd_id}
    job["finished_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    job["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("dd_mutation_jobs.json", jobs)

    # Update cached downtime only after success, idempotent if missing
    now_iso = _iso(datetime.datetime.now(datetime.timezone.utc))
    if downtime_row:
        if downtime_row.get("status") != "cancelled":
            downtime_row["status"] = "cancelled"
        downtime_row["synced_at"] = now_iso
        downtime_row["updated_at"] = now_iso
        _save("dd_resources.json", resources)

    _log("ok", resolved_connection_id=connection_id, mutation_job_id=job_id, cost_units=1)
    return {"mutation_job": job, "downtime_resource": downtime_row}

def create_datadog_connection(workspace_id, name, site, api_key, app_key, rate_limit_per_minute=None, set_as_default=None, **_extra):
    import json, os, datetime, time, re, hashlib, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0395000" if __import__("os").path.isdir("./environment_mix/0395000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return dt

    def _record_log(status, credential_id=None, error=None):
        latency_ms = int((time.time() - _t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + base64.b32encode(os.urandom(16)).decode("ascii").rstrip("=").lower(),
            "endpoint": "create_datadog_connection",
            "workspace_id": workspace_id,
            "connection_id": None,
            "credential_id": credential_id,
            "status": status,
            "error": error,
            "latency_ms": latency_ms,
            "timestamp": _iso(_now),
        })
        _save("request_logs.json", logs)

    def _ulid_ok(v, pat):
        return isinstance(v, str) and re.match(pat, v) is not None

    def _gen_id(prefix):
        return prefix + "_" + base64.b32encode(os.urandom(16)).decode("ascii").rstrip("=").lower()

    # Validate inputs
    if not _ulid_ok(workspace_id, r"^ddws_[0-9A-HJKMNP-TV-Z]{26}$"):
        _record_log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid workspace_id"})
        return _err("VALIDATION_ERROR", "Invalid workspace_id")
    if not isinstance(name, str) or len(name.strip()) < 1 or len(name) > 120:
        _record_log("error", error={"code": "VALIDATION_ERROR", "message": "name must be a non-empty string up to 120 chars"})
        return _err("VALIDATION_ERROR", "name must be a non-empty string up to 120 chars")
    allowed_sites = {"datadoghq.com","us3.datadoghq.com","us5.datadoghq.com","datadoghq.eu","ddog-gov.com","ap1.datadoghq.com"}
    if site not in allowed_sites:
        _record_log("error", error={"code": "VALIDATION_ERROR", "message": "Unsupported site"})
        return _err("VALIDATION_ERROR", "Unsupported site")
    if not isinstance(api_key, str) or api_key.strip() == "":
        _record_log("error", error={"code": "VALIDATION_ERROR", "message": "api_key is required"})
        return _err("VALIDATION_ERROR", "api_key is required")
    if not isinstance(app_key, str) or app_key.strip() == "":
        _record_log("error", error={"code": "VALIDATION_ERROR", "message": "app_key is required"})
        return _err("VALIDATION_ERROR", "app_key is required")
    if rate_limit_per_minute is None:
        rate_limit_per_minute = 60
    if not isinstance(rate_limit_per_minute, int) or rate_limit_per_minute < 1 or rate_limit_per_minute > 6000:
        _record_log("error", error={"code": "VALIDATION_ERROR", "message": "rate_limit_per_minute must be between 1 and 6000"})
        return _err("VALIDATION_ERROR", "rate_limit_per_minute must be between 1 and 6000")
    if set_as_default is None:
        set_as_default = False
    if not isinstance(set_as_default, bool):
        _record_log("error", error={"code": "VALIDATION_ERROR", "message": "set_as_default must be boolean"})
        return _err("VALIDATION_ERROR", "set_as_default must be boolean")

    # Workspace existence
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _record_log("error", error={"code": "NOT_FOUND", "message": "Workspace not found"})
        return _err("NOT_FOUND", "Workspace not found")
    if ws.get("status") != "active":
        _record_log("error", error={"code": "UNAUTHORIZED", "message": "Workspace is not active"})
        return _err("UNAUTHORIZED", "Workspace is not active")

    conns = _load("datadog_connections.json")
    if not isinstance(conns, list):
        conns = []

    # unique(workspace_id, name)
    for c in conns:
        if isinstance(c, dict) and c.get("workspace_id") == workspace_id and (c.get("name") or "").strip().lower() == name.strip().lower():
            _record_log("error", error={"code": "CONFLICT", "message": "Connection name already exists in workspace"})
            return _err("CONFLICT", "Connection name already exists in workspace")

    # Hash keys (store only fingerprint); do not attempt to verify by comparing plaintext later.
    api_key_hash = "sha256:" + hashlib.sha256(api_key.encode("utf-8")).hexdigest()
    app_key_hash = "sha256:" + hashlib.sha256(app_key.encode("utf-8")).hexdigest()

    # "Verify against Datadog" cannot be done offline; mark as error and record last_error
    conn_id = _gen_id("ddconn")
    row = {
        "id": conn_id,
        "workspace_id": workspace_id,
        "name": name.strip(),
        "site": site,
        "api_key_hash": api_key_hash,
        "app_key_hash": app_key_hash,
        "status": "error",
        "last_verified_at": None,
        "last_error": {"code": "UNAUTHORIZED", "message": "Credential verification unavailable in offline datastore"},
        "rate_limit_per_minute": int(rate_limit_per_minute),
        "created_at": _iso(_now),
        "updated_at": _iso(_now),
    }
    conns.append(row)
    _save("datadog_connections.json", conns)

    # Set as default if requested (must belong to same workspace; it does)
    if set_as_default:
        # Enforce workspace lifecycle transitions? Not changing status, only reference.
        ws["default_datadog_connection_id"] = conn_id
        ws["updated_at"] = _iso(_now)
        _save("workspaces.json", workspaces)

    # Return created connection (never return keys)
    resp = dict(row)
    # (keys already not included)
    _record_log("ok", credential_id=conn_id)
    return {"data": resp, "meta": {"verified": False}}

def update_datadog_connection(workspace_id, connection_id, name=None, site=None, api_key=None, app_key=None, rate_limit_per_minute=None, status=None, set_as_default=None, verify_now=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0395000" if __import__("os").path.isdir("./environment_mix/0395000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _iso_parse(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _hash_key(prefix, raw):
        # Stored field is a fingerprint/hash; do not attempt to verify plaintext later.
        h = hashlib.sha256((prefix + ":" + raw).encode("utf-8")).hexdigest()
        return "sha256:" + h

    def _gen_ulid_like(prefix):
        # Deterministic-enough, offline id generator matching pattern: prefix_ + 26 crockford base32
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        # Use time (ms) + pid + some bytes
        t_ms = int(time.time() * 1000)
        payload = (str(t_ms) + ":" + str(os.getpid()) + ":" + str(time.time_ns())).encode("utf-8")
        digest = hashlib.sha256(payload).digest()
        # create 26 chars
        val = int.from_bytes(digest[:16], "big")  # 128 bits
        out = []
        for _ in range(26):
            out.append(alphabet[val & 31])
            val >>= 5
        return prefix + "_" + "".join(out)

    def _log(endpoint, workspace_id, connection_id, status_code, error_code=None, error_message=None, meta=None, started=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now()
        if started is None:
            started = now
        ts0 = _iso_parse(started) or datetime.datetime.utcnow()
        ts1 = _iso_parse(now) or datetime.datetime.utcnow()
        latency_ms = int(max(0, (ts1 - ts0).total_seconds() * 1000))
        row = {
            "id": _gen_ulid_like("ddrl"),
            "ts": now,
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "connection_id": connection_id,
            "status": status_code,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

    started = _now()
    endpoint = "update_datadog_connection"

    # Validate required
    if not isinstance(workspace_id, str) or not re.match(r"^ddws_[0-9A-HJKMNP-TV-Z]{26}$", workspace_id):
        _log(endpoint, workspace_id, connection_id, 400, "VALIDATION_ERROR", "Invalid workspace_id.", started=started)
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(connection_id, str) or not re.match(r"^ddconn_[0-9A-HJKMNP-TV-Z]{26}$", connection_id):
        _log(endpoint, workspace_id, connection_id, 400, "VALIDATION_ERROR", "Invalid connection_id.", started=started)
        return _err("VALIDATION_ERROR", "Invalid connection_id.")

    # Validate optionals
    if name is not None:
        if not isinstance(name, str) or len(name) < 1 or len(name) > 120:
            _log(endpoint, workspace_id, connection_id, 400, "VALIDATION_ERROR", "Invalid name.", started=started)
            return _err("VALIDATION_ERROR", "Invalid name.")
    allowed_sites = {"datadoghq.com", "us3.datadoghq.com", "us5.datadoghq.com", "datadoghq.eu", "ddog-gov.com", "ap1.datadoghq.com"}
    if site is not None:
        if not isinstance(site, str) or site not in allowed_sites:
            _log(endpoint, workspace_id, connection_id, 400, "VALIDATION_ERROR", "Unsupported site.", started=started)
            return _err("VALIDATION_ERROR", "Unsupported site.")
    if api_key is not None:
        if not isinstance(api_key, str) or len(api_key) < 1:
            _log(endpoint, workspace_id, connection_id, 400, "VALIDATION_ERROR", "api_key cannot be empty.", started=started)
            return _err("VALIDATION_ERROR", "api_key cannot be empty.")
    if app_key is not None:
        if not isinstance(app_key, str) or len(app_key) < 1:
            _log(endpoint, workspace_id, connection_id, 400, "VALIDATION_ERROR", "app_key cannot be empty.", started=started)
            return _err("VALIDATION_ERROR", "app_key cannot be empty.")
    if rate_limit_per_minute is not None:
        if not isinstance(rate_limit_per_minute, int) or rate_limit_per_minute < 1 or rate_limit_per_minute > 6000:
            _log(endpoint, workspace_id, connection_id, 400, "VALIDATION_ERROR", "Invalid rate_limit_per_minute.", started=started)
            return _err("VALIDATION_ERROR", "Invalid rate_limit_per_minute.")
    if status is not None:
        if not isinstance(status, str) or status not in {"active", "disabled", "error"}:
            _log(endpoint, workspace_id, connection_id, 400, "VALIDATION_ERROR", "Invalid status.", started=started)
            return _err("VALIDATION_ERROR", "Invalid status.")
    if set_as_default is not None and not isinstance(set_as_default, bool):
        _log(endpoint, workspace_id, connection_id, 400, "VALIDATION_ERROR", "set_as_default must be boolean.", started=started)
        return _err("VALIDATION_ERROR", "set_as_default must be boolean.")
    if verify_now is not None and not isinstance(verify_now, bool):
        _log(endpoint, workspace_id, connection_id, 400, "VALIDATION_ERROR", "verify_now must be boolean.", started=started)
        return _err("VALIDATION_ERROR", "verify_now must be boolean.")

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if ws is None or ws.get("status") == "deleted":
        _log(endpoint, workspace_id, connection_id, 404, "NOT_FOUND", "Workspace not found.", started=started)
        return _err("NOT_FOUND", "Workspace not found.")

    conns = _load("datadog_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn_idx = None
    conn = None
    for i, c in enumerate(conns):
        if c.get("id") == connection_id and c.get("workspace_id") == workspace_id:
            conn_idx = i
            conn = c
            break
    if conn is None:
        _log(endpoint, workspace_id, connection_id, 404, "NOT_FOUND", "Connection not found.", started=started)
        return _err("NOT_FOUND", "Connection not found.")

    # unique(workspace_id, name)
    if name is not None:
        for c in conns:
            if c.get("workspace_id") == workspace_id and c.get("name") == name and c.get("id") != connection_id:
                _log(endpoint, workspace_id, connection_id, 409, "CONFLICT", "Connection name already exists in workspace.", started=started)
                return _err("CONFLICT", "Connection name already exists in workspace.")

    # lifecycle transition
    if status is not None:
        transitions = {
            "active": {"disabled", "error"},
            "error": {"active", "disabled"},
            "disabled": {"active"},
        }
        cur = conn.get("status")
        if cur not in transitions:
            _log(endpoint, workspace_id, connection_id, 400, "VALIDATION_ERROR", "Connection has invalid current status.", started=started)
            return _err("VALIDATION_ERROR", "Connection has invalid current status.")
        if status != cur and status not in transitions[cur]:
            _log(endpoint, workspace_id, connection_id, 409, "INVALID_TRANSITION", f"Cannot transition connection status from {cur} to {status}.", started=started)
            return _err("INVALID_TRANSITION", f"Cannot transition connection status from {cur} to {status}.", from_status=cur, to_status=status)

    # Apply updates
    updated = dict(conn)
    if name is not None:
        updated["name"] = name
    if site is not None:
        updated["site"] = site
    if api_key is not None:
        updated["api_key_hash"] = _hash_key("dd_api", api_key)
        # credentials changed; invalidate verification
        updated["last_verified_at"] = None
    if app_key is not None:
        updated["app_key_hash"] = _hash_key("dd_app", app_key)
        updated["last_verified_at"] = None
    if rate_limit_per_minute is not None:
        updated["rate_limit_per_minute"] = rate_limit_per_minute
    if status is not None:
        updated["status"] = status

    # Optional verify_now: offline "verification" cannot call Datadog; treat as a local credentials-presence check.
    # If keys are present and non-empty hashes exist, consider verified; else mark error.
    if verify_now is True:
        has_keys = bool(updated.get("api_key_hash")) and bool(updated.get("app_key_hash")) and bool(updated.get("site"))
        if has_keys:
            updated["last_verified_at"] = _now()
            updated["last_error"] = None
            # If it was in error, allow moving to active only via lifecycle param; do not auto-transition.
        else:
            updated["last_verified_at"] = None
            updated["last_error"] = {"code": "verification_failed", "message": "Missing site or credentials."}
            # May set status to error as per description.
            cur = updated.get("status")
            if cur != "error":
                # Attempt legal transition to error from current
                transitions = {
                    "active": {"disabled", "error"},
                    "error": {"active", "disabled"},
                    "disabled": {"active"},
                }
                if cur in transitions and "error" in transitions[cur]:
                    updated["status"] = "error"

    updated["updated_at"] = _now()

    conns[conn_idx] = updated
    _save("datadog_connections.json", conns)

    # set as default
    if set_as_default is True:
        ws_updated = dict(ws)
        ws_updated["default_datadog_connection_id"] = connection_id
        ws_updated["updated_at"] = _now()
        # persist workspace update
        for i, w in enumerate(workspaces):
            if w.get("id") == workspace_id:
                workspaces[i] = ws_updated
                break
        _save("workspaces.json", workspaces)

    _log(endpoint, workspace_id, connection_id, 200, started=started)
    return {"data": updated}

def list_datadog_connections(workspace_id, status=None, query=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0395000" if __import__("os").path.isdir("./environment_mix/0395000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _iso_parse(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        t_ms = int(time.time() * 1000)
        payload = (str(t_ms) + ":" + str(os.getpid()) + ":" + str(time.time_ns())).encode("utf-8")
        digest = hashlib.sha256(payload).digest()
        val = int.from_bytes(digest[:16], "big")
        out = []
        for _ in range(26):
            out.append(alphabet[val & 31])
            val >>= 5
        return prefix + "_" + "".join(out)

    def _log(endpoint, workspace_id, connection_id, status_code, error_code=None, error_message=None, meta=None, started=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now()
        if started is None:
            started = now
        ts0 = _iso_parse(started) or datetime.datetime.utcnow()
        ts1 = _iso_parse(now) or datetime.datetime.utcnow()
        latency_ms = int(max(0, (ts1 - ts0).total_seconds() * 1000))
        logs.append({
            "id": _gen_ulid_like("ddrl"),
            "ts": now,
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "connection_id": connection_id,
            "status": status_code,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    started = _now()
    endpoint = "list_datadog_connections"

    if not isinstance(workspace_id, str) or not re.match(r"^ddws_[0-9A-HJKMNP-TV-Z]{26}$", workspace_id):
        _log(endpoint, workspace_id, None, 400, "VALIDATION_ERROR", "Invalid workspace_id.", started=started)
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")

    if status is not None:
        if not isinstance(status, str) or status not in {"active", "disabled", "error"}:
            _log(endpoint, workspace_id, None, 400, "VALIDATION_ERROR", "Invalid status filter.", started=started)
            return _err("VALIDATION_ERROR", "Invalid status filter.")
    if query is not None and not isinstance(query, str):
        _log(endpoint, workspace_id, None, 400, "VALIDATION_ERROR", "query must be a string.", started=started)
        return _err("VALIDATION_ERROR", "query must be a string.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(endpoint, workspace_id, None, 400, "VALIDATION_ERROR", "Invalid limit.", started=started)
        return _err("VALIDATION_ERROR", "Invalid limit.")

    start_offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or len(cursor) < 1:
            _log(endpoint, workspace_id, None, 400, "VALIDATION_ERROR", "Malformed cursor.", started=started)
            return _err("VALIDATION_ERROR", "Malformed cursor.")
        # cursor is base64url-encoded JSON: {"o": int}
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or "o" not in obj or not isinstance(obj["o"], int) or obj["o"] < 0:
                raise ValueError("bad cursor")
            start_offset = obj["o"]
        except Exception:
            _log(endpoint, workspace_id, None, 400, "VALIDATION_ERROR", "Malformed cursor.", started=started)
            return _err("VALIDATION_ERROR", "Malformed cursor.")

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if ws is None or ws.get("status") == "deleted":
        _log(endpoint, workspace_id, None, 404, "NOT_FOUND", "Workspace not found.", started=started)
        return _err("NOT_FOUND", "Workspace not found.")

    conns = _load("datadog_connections.json")
    if not isinstance(conns, list):
        conns = []

    rows = [c for c in conns if c.get("workspace_id") == workspace_id]
    if status is not None:
        rows = [c for c in rows if c.get("status") == status]
    if query is not None and query.strip() != "":
        q = query.strip().lower()
        rows = [c for c in rows if isinstance(c.get("name"), str) and q in c["name"].lower()]

    # Sort by updated_at desc then created_at desc then id
    def _sort_key(c):
        ua = _iso_parse(c.get("updated_at")) or datetime.datetime.min
        ca = _iso_parse(c.get("created_at")) or datetime.datetime.min
        return (ua, ca, c.get("id") or "")
    rows.sort(key=_sort_key, reverse=True)

    total = len(rows)
    page = rows[start_offset:start_offset + limit]
    next_cursor = None
    has_more = start_offset + limit < total
    if has_more:
        obj = {"o": start_offset + limit}
        encoded = base64.urlsafe_b64encode(json.dumps(obj, separators=(",", ":")).encode("utf-8")).decode("utf-8")
        next_cursor = encoded.rstrip("=")

    _log(endpoint, workspace_id, None, 200, meta={"returned": len(page), "total": total}, started=started)
    return {
        "data": page,
        "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor, "limit": limit}
    }

def update_workspace(workspace_id, name=None, status=None, default_datadog_connection_id=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0395000" if __import__("os").path.isdir("./environment_mix/0395000") else "/app/database")
    def _load(n):
