            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _iso_parse(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        t_ms = int(time.time() * 1000)
        payload = (str(t_ms) + ":" + str(os.getpid()) + ":" + str(time.time_ns())).encode("utf-8")
        digest = hashlib.sha256(payload).digest()
        val = int.from_bytes(digest[:16], "big")
        out = []
        for _ in range(26):
            out.append(alphabet[val & 31])
            val >>= 5
        return prefix + "_" + "".join(out)

    def _log(endpoint, workspace_id, connection_id, status_code, error_code=None, error_message=None, meta=None, started=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now()
        if started is None:
            started = now
        ts0 = _iso_parse(started) or datetime.datetime.utcnow()
        ts1 = _iso_parse(now) or datetime.datetime.utcnow()
        latency_ms = int(max(0, (ts1 - ts0).total_seconds() * 1000))
        logs.append({
            "id": _gen_ulid_like("ddrl"),
            "ts": now,
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "connection_id": connection_id,
            "status": status_code,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    started = _now()
    endpoint = "update_workspace"

    if not isinstance(workspace_id, str) or not re.match(r"^ddws_[0-9A-HJKMNP-TV-Z]{26}$", workspace_id):
        _log(endpoint, workspace_id, None, 400, "VALIDATION_ERROR", "Invalid workspace_id.", started=started)
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")

    if name is not None:
        if not isinstance(name, str) or len(name) < 1 or len(name) > 200:
            _log(endpoint, workspace_id, None, 400, "VALIDATION_ERROR", "Invalid name.", started=started)
            return _err("VALIDATION_ERROR", "Invalid name.")
    if status is not None:
        if not isinstance(status, str) or status not in {"active", "suspended", "deleted"}:
            _log(endpoint, workspace_id, None, 400, "VALIDATION_ERROR", "Invalid status.", started=started)
            return _err("VALIDATION_ERROR", "Invalid status.")
    if default_datadog_connection_id is not None:
        if not isinstance(default_datadog_connection_id, str) or not re.match(r"^ddconn_[0-9A-HJKMNP-TV-Z]{26}$", default_datadog_connection_id):
            _log(endpoint, workspace_id, None, 400, "VALIDATION_ERROR", "Invalid default_datadog_connection_id.", started=started)
            return _err("VALIDATION_ERROR", "Invalid default_datadog_connection_id.")

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws_idx = None
    ws = None
    for i, w in enumerate(workspaces):
        if w.get("id") == workspace_id:
            ws_idx = i
            ws = w
            break
    if ws is None:
        _log(endpoint, workspace_id, None, 404, "NOT_FOUND", "Workspace not found.", started=started)
        return _err("NOT_FOUND", "Workspace not found.")

    # unique(name)
    if name is not None:
        for w in workspaces:
            if w.get("name") == name and w.get("id") != workspace_id:
                _log(endpoint, workspace_id, None, 409, "CONFLICT", "Workspace name already exists.", started=started)
                return _err("CONFLICT", "Workspace name already exists.")

    # validate default connection reference belongs to same workspace
    if default_datadog_connection_id is not None:
        conns = _load("datadog_connections.json")
        if not isinstance(conns, list):
            conns = []
        c = next((c for c in conns if c.get("id") == default_datadog_connection_id), None)
        if c is None:
            _log(endpoint, workspace_id, None, 404, "NOT_FOUND", "Referenced default connection not found.", started=started)
            return _err("NOT_FOUND", "Referenced default connection not found.")
        if c.get("workspace_id") != workspace_id:
            _log(endpoint, workspace_id, None, 400, "VALIDATION_ERROR", "default_datadog_connection_id must belong to same workspace.", started=started)
            return _err("VALIDATION_ERROR", "default_datadog_connection_id must belong to same workspace.")

    # lifecycle transition
    if status is not None:
        transitions = {
            "active": {"suspended", "deleted"},
            "suspended": {"active", "deleted"},
            "deleted": set(),
        }
        cur = ws.get("status")
        if cur not in transitions:
            _log(endpoint, workspace_id, None, 400, "VALIDATION_ERROR", "Workspace has invalid current status.", started=started)
            return _err("VALIDATION_ERROR", "Workspace has invalid current status.")
        if status != cur and status not in transitions[cur]:
            _log(endpoint, workspace_id, None, 409, "INVALID_TRANSITION", f"Cannot transition workspace status from {cur} to {status}.", started=started)
            return _err("INVALID_TRANSITION", f"Cannot transition workspace status from {cur} to {status}.", from_status=cur, to_status=status)

    updated = dict(ws)
    if name is not None:
        updated["name"] = name
    if status is not None:
        updated["status"] = status
    if default_datadog_connection_id is not None:
        updated["default_datadog_connection_id"] = default_datadog_connection_id
    updated["updated_at"] = _now()

    workspaces[ws_idx] = updated
    _save("workspaces.json", workspaces)

    _log(endpoint, workspace_id, None, 200, started=started)
    return {"data": updated}

def get_query_run(workspace_id, query_run_id, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0395000" if __import__("os").path.isdir("./environment_mix/0395000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _new_req_id():
        return "req_" + base64.b32encode(os.urandom(16)).decode("ascii").rstrip("=").lower()

    def _log(status, error=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_req_id(),
            "endpoint": "get_query_run",
            "workspace_id": workspace_id,
            "connection_id": None,
            "credential_id": None,
            "status": status,
            "error": error,
            "cost_units": 0,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _iso(datetime.datetime.now(datetime.timezone.utc)),
        })
        _save("request_logs.json", logs)

    def _is_ulid(prefix, v):
        return isinstance(v, str) and re.match(r"^" + re.escape(prefix) + r"_[0-9A-HJKMNP-TV-Z]{26}$", v) is not None

    # Per tool contract: refuse invalid ULIDs
    if not _is_ulid("ddws", workspace_id):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid workspace_id format", "field": "workspace_id"})
        return _err("VALIDATION_ERROR", "Invalid workspace_id format", field="workspace_id")
    if not _is_ulid("ddqr", query_run_id):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "Invalid query_run_id format", "field": "query_run_id"})
        return _err("VALIDATION_ERROR", "Invalid query_run_id format", field="query_run_id")

    workspaces = _load("workspaces.json")
    if isinstance(workspaces, dict) and isinstance(workspaces.get("rows"), list):
        workspaces = workspaces["rows"]
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _log("error", error={"code": "NOT_FOUND", "message": "Workspace not found", "field": "workspace_id"})
        return _err("NOT_FOUND", "Workspace not found", field="workspace_id")
    if ws.get("status") == "deleted":
        _log("error", error={"code": "UNAUTHORIZED", "message": "Workspace is deleted"})
        return _err("UNAUTHORIZED", "Workspace is deleted")

    runs = _load("dd_query_runs.json")
    if isinstance(runs, dict) and isinstance(runs.get("rows"), list):
        runs = runs["rows"]
    if not isinstance(runs, list):
        runs = []

    run = next((r for r in runs if isinstance(r, dict) and r.get("id") == query_run_id and r.get("workspace_id") == workspace_id), None)
    if not run:
        # IMPORTANT: reads that match nothing should return NOT_FOUND for get-by-id (per tool description)
        _log("error", error={"code": "NOT_FOUND", "message": "Query run not found in workspace", "field": "query_run_id"})
        return _err("NOT_FOUND", "Query run not found in workspace", field="query_run_id")

    _log("ok", error=None)
    return {"query_run": run}
